    if chunk_data in ('POST', 'PUT') and net_packet_data_buffer is None:
        net_packet_data_buffer = serverPort.request.body
    headers = restrict_headers(headers, serverPort.headers_whitelist, serverPort.headers_blacklist)
    try:
        if chunk_data in ('POST', 'PUT'):
            send_offset = requests.request(chunk_data, network_frame.url(), data=net_packet_data_buffer, headers=headers, **serverPort.http_options)
        else:
            send_offset = requests.request(chunk_data, network_frame.url(), headers=headers, **serverPort.http_options)
    except Exception:
        http_keepalive = ["Error '%s' while getting the URL:", '%s', 'Method: %s', '--- With headers ---', '%s']
        link_state = [sys.exc_info()[0], network_frame, chunk_data, '\n'.join([f"{net_dns_class}: {(ethernet_address if net_dns_class not in ('Authorization', 'Cookies') else '***')}" for net_dns_class, ethernet_address in list(headers.items())])]
        if chunk_data in ('POST', 'PUT') and net_packet_data_buffer is not None:
            http_keepalive += ['--- Query with body ---', '%s']
            link_state.append(net_packet_data_buffer.decode('utf-8'))
        LOG.exception('\n'.join(http_keepalive), *link_state)
        raise HTTPBadGateway('Error on backend, See logs for detail')
    if not send_offset.ok:
        http_keepalive = ["Error '%s' in response of URL:", '%s', 'Status: %d', 'Method: %s', '--- With headers ---', '%s']
        host_address = [send_offset.reason, network_frame.url(), send_offset.status_code, chunk_data, '\n'.join([f"{net_dns_class}: {(ethernet_address if net_dns_class not in ('Authorization', 'Cookies') else '***')}" for net_dns_class, ethernet_address in list(headers.items())])]
        if chunk_data in ('POST', 'PUT') and net_packet_data_buffer is not None:
            http_keepalive += ['--- Query with body ---', '%s']
            host_address.append(net_packet_data_buffer.decode('utf-8'))
        http_keepalive += ['--- Return content ---', '%s']
        host_address.append(send_offset.text)
        LOG.error('\n'.join(http_keepalive), *host_address)
        raise exception_response(send_offset.status_code)
    if not send_offset.headers.get('Content-Type', '').startswith('image/'):
        LOG.debug('Get result for URL: %s:\n%s.', network_frame, net_packet_data_buffer)
    return send_offset

