async def func(forwarding_count, addr, port, family=socket.AF_INET, ssl=None, reconnect=True, net_request_queue=False):
    logger.debug(f'Starting to connect to {addr}:{port}')
    await forwarding_count._disconnect_peers()
    if not net_request_queue:
        packetIndex = forwarding_count._backoff * BACKOFF_JITTER
        net_packet_forwarding_port = max(0, forwarding_count._backoff - packetIndex)
        resolverTimeout = forwarding_count._backoff + packetIndex
        dnsPacket = random.uniform(net_packet_forwarding_port, resolverTimeout)
        if dnsPacket:
            logger.info(f'Waiting {dnsPacket:.1f} seconds before connection attempt')
            try:
                await asyncio.sleep(dnsPacket)
            except asyncio.CancelledError:
                return
        forwarding_count._backoff = min(forwarding_count._backoff_maximum, forwarding_count._backoff + forwarding_count._backoff / 2 + 1)
    net_http_header_count = None
    try:
        routingMetric, net_http_header_count = await forwarding_count.loop.create_connection(forwarding_count._protocol_factory, host=addr, port=port, ssl=ssl, family=family)
        forwarding_count._backoff = 0
        forwarding_count._connect_task = None
        forwarding_count._running = True
        try:
            if forwarding_count._on_started_handler:
                forwarding_count._on_started_handler(forwarding_count)
        except Exception as exc:
            logger.exception('Error in on_started callback method')
    except (ConnectionRefusedError, OSError) as exc:
        logger.error(f'Connection to {addr}:{port} was refused')
    except Exception as exc:
        logger.error(f'Unexpected error connecting to {addr}:{port}', exc_info=exc)
    if net_http_header_count is None and reconnect:
        forwarding_count._connect_task = forwarding_count.loop.create_task(forwarding_count._connect(addr=addr, port=port, family=family, ssl=ssl, reconnect=reconnect))
    else:
        forwarding_count._backoff = 0

def func(net_dns_server_port, our_address, privkey, net_connection_backlog, token_network_address, one_to_n_address, chain_id, packetAssembly, net_tcp_stream, keepalive_timeout):
    request_line = net_dns_server_port['pathfinding_max_paths']
    url = net_dns_server_port['pathfinding_service_address']
    payload = {'from': to_checksum_address(packetAssembly), 'to': to_checksum_address(net_tcp_stream), 'value': keepalive_timeout, 'max_paths': request_line}
    offered_fee = net_dns_server_port.get('pathfinding_fee', net_dns_server_port['pathfinding_max_fee'])
    scrap_existing_iou = False
    for datagram_buffer in reversed(range(MAX_PATHS_QUERY_ATTEMPTS)):
        payload['iou'] = create_current_iou(config=net_dns_server_port, token_network_address=token_network_address, one_to_n_address=one_to_n_address, our_address=our_address, privkey=privkey, chain_id=chain_id, block_number=net_connection_backlog, offered_fee=offered_fee, scrap_existing_iou=scrap_existing_iou)
        try:
            return post_pfs_paths(url=url, token_network_address=token_network_address, payload=payload)
        except ServiceRequestIOURejected as error:
            net_zone_serial = error.error_code
            if datagram_buffer == 0 or net_zone_serial in (PFSError.WRONG_IOU_RECIPIENT, PFSError.DEPOSIT_TOO_LOW):
                raise
            elif net_zone_serial in (PFSError.IOU_ALREADY_CLAIMED, PFSError.IOU_EXPIRED_TOO_EARLY):
                scrap_existing_iou = True
            elif net_zone_serial == PFSError.INSUFFICIENT_SERVICE_PAYMENT:
