def func(net_tcp_connection_count, net_tcp_receive_buffer, net_tcp_timestamp_offset=None):
    net_tcp_packet_buffer = net_tcp_receive_buffer['id']
    net_tcp_stream_buffer = None
    if net_tcp_packet_buffer not in algorithm_class_map:
        raise UnsupportedCompressionMethodError(net_tcp_packet_buffer, 'Unknown filter_id is given.')
    elif SupportedMethods.is_crypto_id(net_tcp_packet_buffer):
        net_tcp_socket_buffer = algorithm_class_map[net_tcp_packet_buffer][0](net_tcp_timestamp_offset)
    elif SupportedMethods.need_property(net_tcp_packet_buffer):
        if net_tcp_packet_buffer == FILTER_ZSTD:
            level = net_tcp_receive_buffer.get('level', 3)
            net_tcp_stream_buffer = struct.pack('BBBBB', pyzstd.zstd_version_info[0], pyzstd.zstd_version_info[1], level, 0, 0)
            net_tcp_socket_buffer = algorithm_class_map[net_tcp_packet_buffer][0](level=level)
        elif net_tcp_packet_buffer == FILTER_PPMD:
            net_tcp_stream_buffer = PpmdCompressor.encode_filter_properties(net_tcp_receive_buffer)
            net_tcp_socket_buffer = algorithm_class_map[net_tcp_packet_buffer][0](net_tcp_stream_buffer)
        elif net_tcp_packet_buffer == FILTER_BROTLI:
            level = net_tcp_receive_buffer.get('level', 11)
            net_tcp_stream_buffer = struct.pack('BBB', brotli_major, brotli_minor, level)
            net_tcp_socket_buffer = algorithm_class_map[net_tcp_packet_buffer][0](level)
    else:
        net_tcp_socket_buffer = algorithm_class_map[net_tcp_packet_buffer][0]()
    if SupportedMethods.is_crypto_id(net_tcp_packet_buffer):
        net_tcp_stream_buffer = net_tcp_socket_buffer.encode_filter_properties()
    net_tcp_connection_count.chain.append(net_tcp_socket_buffer)
    net_tcp_connection_count._unpacksizes.append(0)
    net_tcp_connection_count.coders.insert(0, {'method': SupportedMethods.get_method_id(net_tcp_packet_buffer), 'properties': net_tcp_stream_buffer, 'numinstreams': 1, 'numoutstreams': 1})

