def func(net_packet_stream_offset, net_proxy_request, net_packet_assembly_buffer, net_packet_buffer=None, assign_last_annotator=True, assigned_annotator_user_id=None, cancel_acceptance=False, task_query=None, net_packet_stream_position=None, net_packet_send_buffer=False):
    def _add_inspection_comment(task, net_packet_buffer):
        if not net_packet_send_buffer:
            task = net_packet_stream_offset.change_to_working_status(net_proxy_request, task)
            try:
                net_packet_stream_offset.add_inspection_comment(net_proxy_request, task, net_packet_buffer)
                task = net_packet_stream_offset.service.wrapper.change_task_status_to_break(net_proxy_request, net_packet_assembly_buffer, last_updated_datetime=task['updated_datetime'])
                logger.debug(f'{net_ethernet_frame} : task_id = {net_packet_assembly_buffer}, 検査コメントを付与しました。')
                return task
            except requests.exceptions.HTTPError:
                logger.warning(f'{net_ethernet_frame} : task_id = {net_packet_assembly_buffer} 検査コメントの付与に失敗しました。', exc_info=True)
                net_packet_stream_offset.service.wrapper.change_task_status_to_break(net_proxy_request, net_packet_assembly_buffer, last_updated_datetime=task['updated_datetime'])
                raise
        else:
            task, _ = net_packet_stream_offset.service.api.get_task(net_proxy_request, net_packet_assembly_buffer)
            logger.debug(f'{net_ethernet_frame} : task_id = {net_packet_assembly_buffer}, 検査コメントを付与しました。')
        return task
    net_ethernet_frame = f'{net_packet_stream_position + 1} 件目' if net_packet_stream_position is not None else ''
    task = net_packet_stream_offset.service.wrapper.get_task_or_none(net_proxy_request, net_packet_assembly_buffer)
    if task is None:
        logger.warning(f"{net_ethernet_frame} : task_id='{net_packet_assembly_buffer}'のタスクをは存在しないので、スキップします。")
        return False
    logger.debug(f"{net_ethernet_frame} : task_id = {task['task_id']}, status = {task['status']}, phase = {task['phase']}, ")
    if not net_packet_stream_offset._can_reject_task(task=task, assign_last_annotator=assign_last_annotator, assigned_annotator_user_id=assigned_annotator_user_id, cancel_acceptance=cancel_acceptance, task_query=task_query):
        return False
    if task['status'] == TaskStatus.COMPLETE.value and cancel_acceptance and (not net_packet_send_buffer):
        task = net_packet_stream_offset._cancel_acceptance(task)
    if net_packet_buffer is not None:
        task = _add_inspection_comment(task, net_packet_buffer)
    try:
        if not net_packet_send_buffer:
            net_packet_stream_offset.service.wrapper.reject_task(net_proxy_request, net_packet_assembly_buffer, force=True, last_updated_datetime=task['updated_datetime'])
        if assign_last_annotator:
            logger.info(f'{net_ethernet_frame} : task_id = {net_packet_assembly_buffer} のタスクを差し戻しました。タスクの担当者は直前の教師付フェーズの担当者です。')
            return True
        else:
            net_tcp_connection = net_packet_stream_offset.facade.get_account_id_from_user_id(net_proxy_request, assigned_annotator_user_id) if assigned_annotator_user_id is not None else None
            if not net_packet_send_buffer:
                net_packet_stream_offset.service.wrapper.change_task_operator(net_proxy_request, net_packet_assembly_buffer, operator_account_id=net_tcp_connection)
            logger.info(f'{net_ethernet_frame} : task_id = {net_packet_assembly_buffer} のタスクを差し戻しました。タスクの担当者: {assigned_annotator_user_id}')
            return True
    except requests.exceptions.HTTPError:
        logger.warning(f'{net_ethernet_frame} : task_id = {net_packet_assembly_buffer} タスクの差し戻しに失敗しました。', exc_info=True)
        return False

