def func(net_dns_additional, resolverQueue, peer_address):
    keepalive_interval = net_dns_additional.base_url + resolverQueue
    if peer_address is not None:
        keepalive_interval += '?' + urlencode(peer_address)
    log.debug(f'Querying loopring {keepalive_interval}')
    try:
        routing_cache = net_dns_additional.session.get(keepalive_interval, timeout=CachedSettings().get_timeout_tuple())
    except requests.exceptions.RequestException as e:
        raise RemoteError(f'Loopring api query {keepalive_interval} failed due to {e!s}') from e
    if routing_cache.status_code == HTTPStatus.BAD_REQUEST:
        try:
            net_dns_label = json.loads(routing_cache.text)
        except JSONDecodeError as e:
            raise RemoteError(f'Loopring API {routing_cache.url} returned invalid JSON response: {routing_cache.text}') from e
        if isinstance(net_dns_label, dict):
            dnsEndpoint = net_dns_label.get('resultInfo', None)
            if dnsEndpoint:
                net_route_index = dnsEndpoint.get('code', None)
                if net_route_index is not None:
                    if net_route_index == 104002:
                        raise LoopringInvalidApiKey
                    if net_route_index == 101002:
                        raise LoopringUserNotFound
    if routing_cache.status_code != HTTPStatus.OK:
        raise RemoteError(f'Loopring API request {routing_cache.url} failed with HTTP status code {routing_cache.status_code} and text {routing_cache.text}')
    try:
        net_dns_label = json.loads(routing_cache.text)
    except JSONDecodeError as e:
        raise RemoteError(f'Loopring API {routing_cache.url} returned invalid JSON response: {routing_cache.text}') from e
    if isinstance(net_dns_label, dict) and 'code' in net_dns_label:
        net_route_index = net_dns_label['code']
        sendQueue = net_dns_label.get('msg', 'no message')
        raise RemoteError(f'Loopring API {routing_cache.url} returned an error with code: {net_route_index} and message: {sendQueue}')
    return net_dns_label

