def func(http_proxy, proxy_target, dns_datagram):
    answerRecord = hide_args(proxy_target, ['--cities-connection-string', '--connection-string'])
    listener_port = 'Launching ' + http_proxy + ' ' + ' '.join(answerRecord)
    dns_datagram.info(re.sub('password=\\w+', 'password=xxxxxxxxx', listener_port))
    proxy_target.insert(0, http_proxy)
    net_request_chunk = subprocess.Popen(proxy_target, stderr=subprocess.PIPE, stdout=subprocess.PIPE, close_fds=True)
    subnetGateway = ''
    try:
        make_async(net_request_chunk.stderr)
        make_async(net_request_chunk.stdout)
        while True:
            select.select([net_request_chunk.stdout, net_request_chunk.stderr], [], [])
            try:
                for http_response in (net_request_chunk.stdout, net_request_chunk.stderr):
                    urlHost = read_async(http_response)
                    if urlHost:
                        net_http_stream, net_tcp_sent_bytes = parse_log(urlHost.decode('utf-8', errors='replace'))
                        for dns_query in net_http_stream:
                            dns_datagram.log(dns_query.level, dns_query.msg)
                            subnetGateway += '##  {}  ##'.format(dns_query.msg)
            except Exception as e:
                dns_datagram.error('error in forwarding logs but process continuing: {}'.format(e))
            if net_request_chunk.poll() is not None:
                break
    finally:
        net_request_chunk.stdout.close()
        net_request_chunk.stderr.close()
    return (net_request_chunk.returncode, subnetGateway)

