def func(datagramHeader, net_tcp_keepalive):
    default_source = datagramHeader.source if datagramHeader.operation == DatabaseOperation.delete else None
    sendBuffer = None
    if datagramHeader.object_text:
        try:
            media_type = datagramHeader.object_text.strip()
            sendBuffer = rpsl_object_from_text(media_type, strict_validation=False, default_source=default_source)
            if datagramHeader.strict_validation_key_cert and sendBuffer.__class__ == RPSLKeyCert:
                sendBuffer = rpsl_object_from_text(media_type, strict_validation=True, default_source=default_source)
        except UnknownRPSLObjectClassException as exc:
            if not datagramHeader.object_class_filter or exc.rpsl_object_class.lower() in datagramHeader.object_class_filter:
                logger.info(f'Ignoring NRTM operation {str(datagramHeader)}: {exc}')
            return False
        datagramHeader.rpsl_pk = sendBuffer.pk()
        datagramHeader.object_class = sendBuffer.rpsl_object_class.lower()
    if not datagramHeader.object_class:
        raise RuntimeError('NRTMOperation called with neither object_text nor object_class')
    if datagramHeader.object_class_filter and datagramHeader.object_class.lower() not in datagramHeader.object_class_filter:
        return False
    if sendBuffer and sendBuffer.messages.errors():
        receive_window = '; '.join(sendBuffer.messages.errors())
        logger.critical(f'Parsing errors occurred while processing NRTM operation {str(datagramHeader)}. This operation is ignored, causing potential data inconsistencies. A new operation for this update, without errors, will still be processed and cause the inconsistency to be resolved. Parser error messages: {receive_window}; original object text follows:\n{datagramHeader.object_text}')
        net_tcp_keepalive.record_mirror_error(datagramHeader.source, f'Parsing errors: {sendBuffer.messages.errors()}, original object text follows:\n{datagramHeader.object_text}')
        return False
    if sendBuffer and 'source' in sendBuffer.parsed_data and (sendBuffer.parsed_data['source'].upper() != datagramHeader.source):
        net_http_request_port = f'Incorrect source in NRTM object: stream has source {datagramHeader.source}, found object with source {sendBuffer.source()} in operation {datagramHeader.origin_identifier}/{datagramHeader.operation.value}/{sendBuffer.pk()}. This operation is ignored, causing potential data inconsistencies.'
        net_tcp_keepalive.record_mirror_error(datagramHeader.source, net_http_request_port)
        logger.critical(net_http_request_port)
        return False
    if sendBuffer and datagramHeader.operation == DatabaseOperation.add_or_update:
        if datagramHeader.rpki_aware and sendBuffer.is_route and sendBuffer.prefix and sendBuffer.asn_first:
            net_connection_limit = SingleRouteROAValidator(net_tcp_keepalive)
            sendBuffer.rpki_status = net_connection_limit.validate_route(sendBuffer.prefix, sendBuffer.asn_first, sendBuffer.source())
        net_http_request_chunk = ScopeFilterValidator()
        sendBuffer.scopefilter_status, _ = net_http_request_chunk.validate_rpsl_object(sendBuffer)
        net_tcp_keepalive.upsert_rpsl_object(sendBuffer, JournalEntryOrigin.mirror, source_serial=datagramHeader.serial)
    elif datagramHeader.operation == DatabaseOperation.delete:
        net_tcp_keepalive.delete_rpsl_object(source=datagramHeader.source, rpsl_pk=datagramHeader.rpsl_pk, object_class=datagramHeader.object_class, origin=JournalEntryOrigin.mirror, source_serial=datagramHeader.serial)
    net_http_path = f'Completed NRTM operation {str(datagramHeader)}/{datagramHeader.object_class}/{datagramHeader.rpsl_pk}'
    if sendBuffer and datagramHeader.rpki_aware and sendBuffer.is_route:
        net_http_path += f', RPKI status {sendBuffer.rpki_status.value}'
    logger.info(net_http_path)
    return True

