def func(net_zone_retry, peerPort, deserialize=True, net_link_delay=False):
    if net_link_delay:
        if 'state' in peerPort:
            raise StateUpdateProhibitedError()
        for domain_label in net_zone_retry.schema.__protected_fields__:
            if domain_label in peerPort.keys():
                raise UnprocessableError('%s is not allowed to be set in this context' % domain_label)
        for net_proxy_target, remote_address in net_zone_retry.schema.__dataclass_fields__.items():
            if net_proxy_target in peerPort.keys() and (not remote_address.metadata.get('initializable', True)):
                raise UnprocessableError('%s is not allowed to be set in this context' % net_proxy_target)
    peerPort = net_zone_retry.schema.validate(net_zone_retry.request, peerPort, deserialize=deserialize, context=net_zone_retry)
    net_zone_retry.before_create(peerPort)
    dns_suffix = net_zone_retry.app.get_default_identifier(net_zone_retry.schema, peerPort, net_zone_retry.request)
    if dns_suffix and net_zone_retry.get(dns_suffix):
        raise net_zone_retry.exist_exc(dns_suffix)
    peerPort = net_zone_retry.storage.set_schema_defaults(peerPort)
    for udpDatagram, dnsSuffix in net_zone_retry.schema.__dataclass_fields__.items():
        if peerPort[udpDatagram] is not None:
            continue
        dns_question_count = dnsSuffix.default_factory
        if not isinstance(dns_question_count, dataclasses._MISSING_TYPE):
            peerPort[udpDatagram] = dns_question_count()
        if peerPort[udpDatagram] is not None:
            continue
        proxy_port = dnsSuffix.metadata.get('default_factory', None)
        if proxy_port:
            peerPort[udpDatagram] = proxy_port(net_zone_retry, net_zone_retry.request)
    net_tcp_segment_length = getattr(net_zone_retry.schema, '__unique_constraint__', None)
    if net_tcp_segment_length:
        net_packet_send_queue = []
        net_dns_index = []
        for net_response_status in net_tcp_segment_length:
            net_packet_send_queue.append(rulez.field[net_response_status] == peerPort[net_response_status])
            net_dns_index.append(f'{net_response_status}=({peerPort[net_response_status]})')
        if net_zone_retry.search(rulez.and_(*net_packet_send_queue)):
            raise net_zone_retry.exist_exc(' '.join(net_dns_index))
    net_zone_retry.update_computed_fields(peerPort)
    dnsAlias = net_zone_retry._create(peerPort)
    dnsAlias.set_initial_state()
    responseLength = net_zone_retry.request.app.dispatcher(signals.OBJECT_CREATED)
    responseLength.dispatch(net_zone_retry.request, dnsAlias)
    dnsAlias.after_created()
    dnsAlias.save()
    return dnsAlias

def func(httpStatusLine):
    def with_arg(dnsResponse):
        @functools.wraps(dnsResponse)
        async def wrapper(**resolverConfig):
            router = resolverConfig['request']
            dnsFlags = router.app.config.recaptcha
            chunkCount = None
            if RECAPTCHA_FIELD in router:
                chunkCount = router[RECAPTCHA_FIELD]
            else:
                for net_dns_rcode in resolverConfig.values():
                    if isinstance(net_dns_rcode, dict) and RECAPTCHA_FIELD in net_dns_rcode:
                        chunkCount = net_dns_rcode.pop(RECAPTCHA_FIELD)
                        break
            if not dnsFlags.active:
                return await dnsResponse(**resolverConfig)
            if chunkCount:
                async with aiohttp.ClientSession() as datagram:
                    async with datagram.post(dnsFlags.url, data={'secret': dnsFlags.secret, 'response': chunkCount}) as net_http_chunk:
                        if net_http_chunk.status == aiohttp.web.HTTPOk.status_code:
                            data = await net_http_chunk.json()
                            if data['success']:
                                return await dnsResponse(**resolverConfig)
            raise HTTPNotAcceptable(reason='Wrong recaptcha')
        return wrapper
    if not callable(httpStatusLine):
        return with_arg
    return with_arg(httpStatusLine)

