            answerRecord.data[DOMAIN] = {'controller': teslaApi(net_tcp_window, endpoint_port, net_dns_resolver_timeout), 'devices': defaultdict(list)}
            _LOGGER.debug('Connected to the Tesla API.')
        except HTTPError as ex:
            if ex.code == 401:
                answerRecord.components.persistent_notification.create('Error:<br />Please check username and password.You will need to restart Home Assistant after fixing.', title=NOTIFICATION_TITLE, notification_id=NOTIFICATION_ID)
            else:
                answerRecord.components.persistent_notification.create("Error:<br />Can't communicate with Tesla API.<br />Error code: {} Reason: {}You will need to restart Home Assistant after fixing.".format(ex.code, ex.reason), title=NOTIFICATION_TITLE, notification_id=NOTIFICATION_ID)
            _LOGGER.error('Unable to communicate with Tesla API: %s', ex.reason)
            return False
    net_http_method = answerRecord.data[DOMAIN]['controller'].list_vehicles()
    if not net_http_method:
        return False
    for net_chunk_index in net_http_method:
        answerRecord.data[DOMAIN]['devices'][net_chunk_index.hass_type].append(net_chunk_index)
    for net_tcp_slow_start_threshold in TESLA_COMPONENTS:
