def func(tcpWindow, link_capacity, packet_queue, tcpWindowSize, resolver_port):
    dnsQueryClass = []
    dns_label = 0
    for httpUserAgent in tcpWindow:
        net_listener_port = packet_queue.functions.claim(sender=httpUserAgent.sender, receiver=httpUserAgent.receiver, amount=httpUserAgent.amount, claimable_until=httpUserAgent.claimable_until, signature=httpUserAgent.signature)
        net_dns_zone_name = net_listener_port.call()
        if net_dns_zone_name < link_capacity:
            print('Not enough user deposit to claim profitably for', httpUserAgent)
            dns_label += 1
            continue
        net_domain_name = net_listener_port.transact()
        dnsQueryClass.append((net_domain_name, httpUserAgent))
    net_http_stream = 0
    while dnsQueryClass:
        for net_domain_name, httpUserAgent in dnsQueryClass.copy():
            try:
                dnsCount = tcpWindowSize.eth.get_transaction_receipt(net_domain_name)
            except TransactionNotFound:
                continue
            dnsQueryClass.remove((net_domain_name, httpUserAgent))
            if dnsCount['status'] == 1:
                print(f'Successfully claimed {httpUserAgent}.')
                httpUserAgent.claimed = True
                resolver_port.upsert_iou(httpUserAgent)
            else:
                print(f'Claiming {httpUserAgent} failed!')
                net_http_stream += 1
    return (dns_label, net_http_stream)

def func(net_packet_batch_buffer, net_packet_assembly_buffer, net_packet_total_bytes, net_packet_header_bytes, net_packet_frame_length=None, phase=None, net_packet_index=None):
    if net_packet_batch_buffer.executor_server.verbose:
        net_packet_data = '-vvv'
    else:
        net_packet_data = '-v'
    net_packet_send_buffer = [net_packet_batch_buffer.executor_server.ansible_manager.getAnsibleCommand(net_packet_header_bytes), net_packet_data, net_packet_assembly_buffer.path]
    if net_packet_assembly_buffer.secrets_content:
        net_packet_send_buffer.extend(['-e', '@' + net_packet_assembly_buffer.secrets])
    net_packet_send_buffer.extend(['-e', '@' + net_packet_batch_buffer.jobdir.extra_vars])
    if net_packet_frame_length is not None:
        net_packet_send_buffer.extend(['-e', 'zuul_success=%s' % str(bool(net_packet_frame_length))])
    if phase:
        net_packet_send_buffer.extend(['-e', 'zuul_execution_phase=%s' % phase])
    if net_packet_index is not None:
        net_packet_send_buffer.extend(['-e', 'zuul_execution_phase_index=%s' % net_packet_index])
    net_packet_send_buffer.extend(['-e', 'zuul_execution_trusted=%s' % str(net_packet_assembly_buffer.trusted)])
    net_packet_send_buffer.extend(['-e', 'zuul_execution_canonical_name_and_path=%s' % net_packet_assembly_buffer.canonical_name_and_path])
    net_packet_send_buffer.extend(['-e', 'zuul_execution_branch=%s' % str(net_packet_assembly_buffer.branch)])
    if net_packet_batch_buffer.executor_variables_file is not None:
        net_packet_send_buffer.extend(['-e@%s' % net_packet_batch_buffer.executor_variables_file])
    net_packet_batch_buffer.emitPlaybookBanner(net_packet_assembly_buffer, 'START', phase)
    result, net_packet_fragment_buffer = net_packet_batch_buffer.runAnsible(net_packet_send_buffer, net_packet_total_bytes, net_packet_assembly_buffer, net_packet_header_bytes, cleanup=phase == 'cleanup')
    net_packet_batch_buffer.log.debug('Ansible complete, result %s code %s' % (net_packet_batch_buffer.RESULT_MAP[result], net_packet_fragment_buffer))
    if net_packet_batch_buffer.executor_server.statsd:
        net_packet_channel_index = 'zuul.executor.{hostname}.phase.{phase}'
        net_packet_batch_buffer.executor_server.statsd.incr(net_packet_channel_index + '.{result}', result=net_packet_batch_buffer.RESULT_MAP[result], phase=phase or 'unknown')
    net_packet_batch_buffer.emitPlaybookBanner(net_packet_assembly_buffer, 'END', phase, result=result)
    return (result, net_packet_fragment_buffer)

