def func():
    proxyQueue = {}
    @callback
    def store_credentials(net_chunk_offset, zoneRetry):
        tcp_segment_size = uuid.uuid4().hex
        proxyQueue[net_chunk_offset, tcp_segment_size] = (dt_util.utcnow(), zoneRetry)
        return tcp_segment_size
    @callback
    def retrieve_credentials(net_chunk_offset, tcp_segment_size):
        endpointAddress = (net_chunk_offset, tcp_segment_size)
        if endpointAddress not in proxyQueue:
            return None
        httpServer, zoneRetry = proxyQueue.pop(endpointAddress)
        if dt_util.utcnow() - httpServer < timedelta(minutes=10):
            return zoneRetry
        return None
    return (store_credentials, retrieve_credentials)

