def func(status_line, route_path, nextHop, sent_bytes, dns_server=None):
    request_query = {'method': nextHop, 'params': sent_bytes, 'version': '1.1', 'id': str(_random.random())[2:]}
    if dns_server:
        if type(dns_server) is not dict:
            raise ValueError('context is not type dict as required.')
        request_query['context'] = dns_server
    packetPort = _json.dumps(request_query, cls=_JSONObjectEncoder)
    net_send_queue = _requests.post(route_path, data=packetPort, headers=status_line._headers, timeout=status_line.timeout, verify=not status_line.trust_all_ssl_certificates)
    net_send_queue.encoding = 'utf-8'
    if net_send_queue.status_code == 500:
        if net_send_queue.headers.get(_CT) == _AJ:
            httpUserAgent = net_send_queue.json()
            if 'error' in httpUserAgent:
                raise ServerError(**httpUserAgent['error'])
            else:
                raise ServerError('Unknown', 0, net_send_queue.text)
        else:
            raise ServerError('Unknown', 0, net_send_queue.text)
    if not net_send_queue.ok:
        net_send_queue.raise_for_status()
    dnsReferral = net_send_queue.json()
    if 'result' not in dnsReferral:
        raise ServerError('Unknown', 0, 'An unknown server error occurred')
    if not dnsReferral['result']:
        return
    if len(dnsReferral['result']) == 1:
        return dnsReferral['result'][0]
    return dnsReferral['result']

