                proxy_buffer = utils.rzpad(routerInterface, 32)
                dnsEndpoint.append(int.from_bytes(utils.sha3(proxy_buffer + retransmitQueue), byteorder='big'))
            address_record = len(dnsEndpoint)
            if address_record == 1:
                routerPort = dnsEndpoint[0]
        else:
            if len(http_body) >= 4:
                raise CriticalError('Invalid number of parameters.')
            if len(http_body) >= 1:
                routerPort = int(http_body[0])
            if len(http_body) >= 2:
                address_record = int(http_body[1])
            if len(http_body) == 3 and http_body[2] == 'array':
                retransmitQueue = utils.zpad(utils.int_to_big_endian(routerPort), 32)
                routerPort = int.from_bytes(utils.sha3(retransmitQueue), byteorder='big')
    except ValueError:
        raise CriticalError('Invalid storage index. Please provide a numeric value.')
    net_dns_server_port = []
    try:
        if address_record == 1:
            net_dns_server_port.append('{}: {}'.format(routerPort, header_field.eth.eth_getStorageAt(stream_buffer, routerPort)))
        elif len(dnsEndpoint) > 0:
            for udp_peer in range(0, len(dnsEndpoint)):
                routerPort = dnsEndpoint[udp_peer]
                net_dns_server_port.append('{}: {}'.format(hex(routerPort), header_field.eth.eth_getStorageAt(stream_buffer, routerPort)))
        else:
            for udp_peer in range(routerPort, routerPort + address_record):
                net_dns_server_port.append('{}: {}'.format(hex(udp_peer), header_field.eth.eth_getStorageAt(stream_buffer, udp_peer)))
    except FileNotFoundError as e:
        raise CriticalError('IPC error: ' + str(e))
    except ConnectionError:
        raise CriticalError('Could not connect to RPC server. Make sure that your node is running and that RPC parameters are set correctly.')
    return '\n'.join(net_dns_server_port)

def func(dns_pointer):
    if isinstance(dns_pointer.curve.model, ShortWeierstrassModel):
        if dns_pointer.order * dns_pointer.cofactor % 2 != 0:
            return None
        net_connection_index = FF(dns_pointer.curve.prime)
        stream_buffer = sympify('x^3 + a * x + b', evaluate=False)
        stream_buffer = stream_buffer.subs('a', net_connection_index(int(dns_pointer.curve.parameters['a'])))
        stream_buffer = stream_buffer.subs('b', net_connection_index(int(dns_pointer.curve.parameters['b'])))
        packet_source = Poly(stream_buffer, symbols('x'), domain=net_connection_index)
        dns_port = packet_source.ground_roots()
        if not dns_port:
            return None
        x = Mod(int(next(iter(dns_port.keys()))), dns_pointer.curve.prime)
        return Point(AffineCoordinateModel(dns_pointer.curve.model), x=x, y=Mod(0, dns_pointer.curve.prime))
    elif isinstance(dns_pointer.curve.model, MontgomeryModel):
        return Point(AffineCoordinateModel(dns_pointer.curve.model), x=Mod(0, dns_pointer.curve.prime), y=Mod(0, dns_pointer.curve.prime))
    else:
        raise NotImplementedError

