def func(net_packet_assembly_buffer, net_packet_data_buffer):
    net_packet_assembly_buffer._acquire_lock()
    try:
        dir, net_packet_bytes = split(net_packet_data_buffer)
        net_packet_sequence_number = net_packet_assembly_buffer.load_index(dir, 'res_index', {})
        try:
            net_packet_fragment_buffer, net_packet_total_bytes, net_packet_data_length = net_packet_sequence_number[net_packet_bytes]
        except KeyError:
            return
        try:
            net_packet_window_offset = net_packet_assembly_buffer.load_index(dir, 'blob_index')
        except EnvironmentError as ex:
            net_packet_assembly_buffer.db.corruption('LangZone.remove_path', "could not read blob_index for '%s' dir: %s" % (dir, ex), 'recover')
            net_packet_window_offset = {}
        net_packet_receive_buffer = net_packet_assembly_buffer.lang in net_packet_assembly_buffer.db.import_everything_langs
        if net_packet_receive_buffer:
            try:
                net_packet_header_offset = net_packet_assembly_buffer.load_index(dir, 'toplevelname_index')
            except EnvironmentError as ex:
                net_packet_assembly_buffer.db.corruption('LangZone.remove_path', "could not read toplevelname_index for '%s' dir: %s" % (dir, ex), 'recover')
                net_packet_header_offset = net_packet_assembly_buffer.toplevelname_index_class()
        net_packet_frame_buffer = net_packet_assembly_buffer.dhash_from_dir(dir)
        del net_packet_sequence_number[net_packet_bytes]
        for net_packet_frame_length in net_packet_data_length:
            try:
                net_packet_data = net_packet_window_offset[net_packet_frame_length]
            except KeyError:
                net_packet_queue_offset = join(net_packet_frame_buffer, 'blob_index')
                net_packet_assembly_buffer.db.corruption('LangZone.remove_path', "'%s' blob not in '%s'" % (net_packet_frame_length, net_packet_queue_offset), 'ignore')
                continue
            del net_packet_window_offset[net_packet_frame_length]
            for net_packet_data_buffer in glob(join(net_packet_assembly_buffer.base_dir, net_packet_frame_buffer, net_packet_data + '.*')):
                log.debug("fs-write: remove %s blob file '%s/%s'", net_packet_assembly_buffer.lang, net_packet_frame_buffer, basename(net_packet_data_buffer))
                os.remove(net_packet_data_buffer)
        if net_packet_receive_buffer:
            net_packet_header_offset.remove(net_packet_bytes, net_packet_data_length)
        net_packet_assembly_buffer.changed_index(dir, 'res_index')
        net_packet_assembly_buffer.changed_index(dir, 'blob_index')
        if net_packet_receive_buffer:
            net_packet_assembly_buffer.changed_index(dir, 'toplevelname_index')
    finally:
        net_packet_assembly_buffer._release_lock()

