def func(net_packet_destination_address, net_packet_frame_buffer):
    net_packet_batch_buffer = ''
    net_packet_data = None
    net_packet_fragment_buffer = re.split('\\s+(and|or|not)\\s+', net_packet_frame_buffer, re.IGNORECASE)
    for net_packet_frame_length in net_packet_fragment_buffer:
        if net_packet_frame_length in ('and', 'or', 'not'):
            net_packet_batch_buffer += ' ' + net_packet_frame_length + ' '
            continue
        net_packet_send_buffer = re.match('^code#([a-zA-Z0-9\\s,\\[\\]]+)#', net_packet_frame_length)
        if net_packet_send_buffer:
            if net_packet_data is None:
                net_packet_data = net_packet_destination_address.get_easm()
            net_packet_assembly_buffer = net_packet_send_buffer.group(1).replace(',', '\\n')
            net_packet_batch_buffer += '"' + net_packet_assembly_buffer + '" in easm_code'
            continue
        net_packet_send_buffer = re.match('^func#([a-zA-Z0-9\\s_,(\\\\)\\[\\]]+)#$', net_packet_frame_length)
        if net_packet_send_buffer:
            net_packet_frame_offset = '0x' + utils.sha3(net_packet_send_buffer.group(1))[:4].hex()
            net_packet_batch_buffer += '"' + net_packet_frame_offset + '" in self.disassembly.func_hashes'
            continue
    return eval(net_packet_batch_buffer.strip())

