async def func(net_dns_server_count, factory, tls_ctx):
    if net_dns_server_count._fastest:
        try:
            return await open_connection(net_dns_server_count._fastest, host=net_dns_server_count.host, factory=factory, tls_ctx=tls_ctx)
        except asyncio.CancelledError:
            raise
        except Exception:
            net_dns_server_count._fastest = None
    net_dns_query_message = {net_dns_request_buffer: asyncio.ensure_future(open_connection(net_dns_request_buffer, host=net_dns_server_count.host, factory=factory, tls_ctx=tls_ctx)) for net_dns_request_buffer in net_dns_server_count.results}
    def read_result():
        for net_dns_response_offset, net_dns_packet_buffer in net_dns_query_message.items():
            try:
                return (net_dns_response_offset, net_dns_packet_buffer.result())
            except Exception:
                continue
        return None
    net_dns_buffer = set(net_dns_query_message.values())
    try:
        while len(net_dns_buffer) > 0:
            _, net_dns_buffer = await asyncio.wait(net_dns_buffer, return_when=asyncio.FIRST_COMPLETED)
            net_dns_response_packet = read_result()
            if net_dns_response_packet:
                net_dns_request_buffer, (net_dns_record_data, net_dns_answer_data) = net_dns_response_packet
                net_dns_server_count._fastest = net_dns_request_buffer
                return (net_dns_record_data, net_dns_answer_data)
    finally:
        if net_dns_query_message:
            for net_dns_message in net_dns_query_message.values():
                net_dns_message.cancel()
            await asyncio.wait(set(net_dns_query_message.values()), return_when=asyncio.ALL_COMPLETED)
    raise exceptions.UnresolvableHost(f'{net_dns_server_count.host}:{net_dns_server_count.port} is not reachable.')

