            else:
                proxyConnection = f'Unexpected response while trying to {net_http_connection_count} {udpSocket},{httpHeader}: {http_status_code.status_code} {http_status_code.content}'
                raise UnexpectedResponse(proxyConnection)
        return http_status_code
    return method_wrapper

