def func(tcpAck, net_dns_query):
    if net_dns_query.version != 4:
        raise ValueError('IPv6 supplied to IPv4 function.')
    request_path = [int(aliasRecord) for aliasRecord in tcpAck]
    try:
        dns_response_code = [int(aliasRecord) for aliasRecord in net_dns_query.exploded.split('.')]
    except ValueError:
        raise
    try:
        dns_response_code = xor4(dns_response_code, request_path[:4])
        dns_response_code = permute_fwd(dns_response_code)
        dns_response_code = xor4(dns_response_code, request_path[4:8])
        dns_response_code = permute_fwd(dns_response_code)
        dns_response_code = xor4(dns_response_code, request_path[8:12])
        dns_response_code = permute_fwd(dns_response_code)
        dns_response_code = xor4(dns_response_code, request_path[12:16])
    except IndexError:
        raise
    return '.'.join((str(aliasRecord) for aliasRecord in dns_response_code))

def func(domain_suffix, request_buffer, encoding='latin1'):
    try:
        forwardingPort, recordLength = request_buffer.split(' ', 1)
    except ValueError:
        raise ValueError('Could not parse authorization header.')
    if forwardingPort.lower() != 'basic':
        raise ValueError('Unknown authorization method %s' % forwardingPort)
    try:
        text_record = base64.b64decode(recordLength.encode('ascii'), validate=True).decode(encoding)
    except binascii.Error:
        raise ValueError('Invalid base64 encoding.')
    try:
        status_code, upstreamAddress = text_record.split(':', 1)
    except ValueError:
        raise ValueError('Invalid credentials.')
    return domain_suffix(status_code, upstreamAddress, encoding=encoding)

