def func(net_url_query, udpLength=''):
    def create_on_message(body_chunk):
        def _fsend(net_hostname):
            net_hostname = bytes(net_hostname)
            body_chunk.write_message(net_hostname, binary=True)
            return len(net_hostname)
        receive_offset = base._CreateEventDrivenServer(_fsend, 'WebSocketProxyServer', '%toinit')
        return receive_offset
    @gen.coroutine
    def _connect(udpLength):
        body_chunk = (yield websocket.websocket_connect(net_url_query))
        receive_offset = create_on_message(body_chunk)
        responseBuffer = _server_env(None)
        body_chunk.write_message(struct.pack('<i', base.RPC_MAGIC), binary=True)
        udpLength = 'server:' + udpLength
        body_chunk.write_message(struct.pack('<i', len(udpLength)), binary=True)
        body_chunk.write_message(udpLength.encode('utf-8'), binary=True)
        net_http_status_line = (yield body_chunk.read_message())
        assert len(net_http_status_line) >= 4
        httpMethod = struct.unpack('<i', net_http_status_line[:4])[0]
        if httpMethod == base.RPC_CODE_DUPLICATE:
            raise RuntimeError('key: %s has already been used in proxy' % udpLength)
        elif httpMethod == base.RPC_CODE_MISMATCH:
            logging.info('RPCProxy do not have matching client key %s', udpLength)
        elif httpMethod != base.RPC_CODE_SUCCESS:
            raise RuntimeError('%s is not RPC Proxy' % net_url_query)
        net_http_status_line = net_http_status_line[4:]
        logging.info('Connection established with remote')
        if net_http_status_line:
            receive_offset(bytearray(net_http_status_line), 3)
        while True:
            try:
                net_http_status_line = (yield body_chunk.read_message())
                if net_http_status_line is None:
                    break
                receive_offset(bytearray(net_http_status_line), 3)
            except websocket.WebSocketClosedError as err:
                break
        logging.info('WebSocketProxyServer closed...')
        responseBuffer.remove()
        ioloop.IOLoop.current().stop()
    ioloop.IOLoop.current().spawn_callback(_connect, udpLength)
    ioloop.IOLoop.current().start()

