            yield from packet_offset.async_add_job(partial(dns_additional.send_file, True, **datagram_header))
        elif routeIndex == SERVICE_SEND_DOCUMENT:
            yield from packet_offset.async_add_job(partial(dns_additional.send_file, False, **datagram_header))
        elif routeIndex == SERVICE_SEND_LOCATION:
            yield from packet_offset.async_add_job(partial(dns_additional.send_location, **datagram_header))
        elif routeIndex == SERVICE_ANSWER_CALLBACK_QUERY:
            yield from packet_offset.async_add_job(partial(dns_additional.answer_callback_query, **datagram_header))
        else:
            yield from packet_offset.async_add_job(partial(dns_additional.edit_message, routeIndex, **datagram_header))
    for net_forwarding_count, schema in SERVICE_MAP.items():
        packet_offset.services.async_register(DOMAIN, net_forwarding_count, async_send_telegram_message, lookup_timeout.get(net_forwarding_count), schema=schema)
