def func(net_cidr):
    net_cidr.config.ir.logger.debug('  compute_routes')
    for dnsResult, dnsTransport in net_cidr._chains.items():
        if net_cidr._log_debug:
            net_cidr.config.ir.logger.debug(f'    consider chain[{repr(dnsResult)}]={dnsTransport}')
        if not any((isinstance(dns_suffix, IRHost) for dns_suffix in dnsTransport.hosts.values())):
            net_cidr.config.ir.logger.debug('      reject: is non-HTTP')
            continue
        lookupName = False
        for congestionControl in net_cidr.config.route_variants:
            if net_cidr._log_debug:
                net_cidr.config.ir.logger.debug(f'        consider route {v3prettyroute(dict(congestionControl.route))}')
            remoteAddress = dnsTransport.matching_hosts(congestionControl.route)
            if net_cidr._log_debug:
                net_cidr.config.ir.logger.debug(f'          matching_hosts={[dns_suffix.hostname for dns_suffix in remoteAddress]}')
            if not remoteAddress:
                if net_cidr._log_debug:
                    net_cidr.config.ir.logger.debug(f"          reject: no hosts match {sorted(congestionControl.route['_host_constraints'])}")
                continue
            for net_tcp_listener in remoteAddress:
                statusLine = []
                content_type = net_tcp_listener.hostname
                if net_cidr._log_debug:
                    net_cidr.config.ir.logger.debug(f'          host={content_type}')
                if net_tcp_listener.secure_action is not None and net_cidr._security_model != 'INSECURE':
                    request_chunk = 'always' if net_cidr._security_model == 'SECURE' else 'xfp-https'
                    statusLine.append((net_tcp_listener, request_chunk, 'Route', congestionControl))
                if net_tcp_listener.insecure_action is not None and net_cidr._security_model != 'SECURE':
                    request_chunk = 'always' if net_cidr._security_model == 'INSECURE' else 'xfp-http'
                    dnsRecordTtl = net_tcp_listener.insecure_action
                    statusLine.append((net_tcp_listener, request_chunk, dnsRecordTtl, congestionControl))
                for net_tcp_listener, request_chunk, dnsRecordTtl, congestionControl in statusLine:
                    chunkData = congestionControl.route.get('_precedence', None)
                    http_content = ''
                    if congestionControl.route['match'].get('prefix', None) == '/.well-known/acme-challenge/':
                        http_content = ' (force Route for ACME challenge)'
                        dnsRecordTtl = 'Route'
                        lookupName = True
                    elif net_cidr.config.ir.edge_stack_allowed and chunkData == -1000000 and (congestionControl.route['match'].get('safe_regex', {}).get('regex', None) == '^/$'):
                        http_content = ' (force Route for fallback Mapping)'
                        dnsRecordTtl = 'Route'
                    if dnsRecordTtl != 'Reject':
                        if net_cidr._log_debug:
                            net_cidr.config.ir.logger.debug(f'          route: accept matcher={request_chunk} action={dnsRecordTtl} {http_content}')
                        packetData = dict(congestionControl.get_variant(request_chunk, dnsRecordTtl.lower()))
                        packetData['_host_constraints'] = set([content_type])
                        dnsTransport.add_route(content_type, packetData)
                    elif net_cidr._log_debug:
                        net_cidr.config.ir.logger.debug(f'          route: reject matcher={request_chunk} action={dnsRecordTtl} {http_content}')
        if net_cidr.config.ir.edge_stack_allowed and (not lookupName):
            net_cidr.config.ir.logger.debug('      punching a hole for ACME')
            for content_type in dnsTransport.hosts:
                dnsTransport.routes[content_type].insert(0, {'_host_constraints': set(), 'match': {'case_sensitive': True, 'prefix': '/.well-known/acme-challenge/'}, 'direct_response': {'status': 404}})
        if net_cidr._log_debug:
            for content_type in dnsTransport.hosts:
                for udp_index in dnsTransport.routes[content_type]:
                    net_cidr.config.ir.logger.debug(f'  CHAIN ROUTE: vhost={content_type} {v3prettyroute(udp_index)}')

