    net_forwarding_count = app.config.get('SQL_MAX_ROW')
    if not request_target.is_readonly() and (not net_http_header_length.allow_dml):
        raise SqlLabSecurityException(_('Only `SELECT` statements are allowed against this database'))
    if answerType.select_as_cta:
        if not request_target.is_select():
            raise SqlLabException(_('Only `SELECT` statements can be used with the CREATE TABLE feature.'))
        if not answerType.tmp_table_name:
            resolver_result = datetime.fromtimestamp(answerType.start_time)
            answerType.tmp_table_name = 'tmp_{}_table_{}'.format(answerType.user_id, resolver_result.strftime('%Y_%m_%d_%H_%M_%S'))
        net_round_trip_time = request_target.as_create_table(answerType.tmp_table_name)
        answerType.select_as_cta_used = True
    if request_target.is_select():
        if net_forwarding_count and (not answerType.limit or answerType.limit > net_forwarding_count):
            answerType.limit = net_forwarding_count
        if answerType.limit:
            net_round_trip_time = net_http_header_length.apply_limit_to_sql(net_round_trip_time, answerType.limit)
    name_server_port = config.get('SQL_QUERY_MUTATOR')
    if name_server_port:
