        await dns_buffer._reedem_download(net_tcp_throughput_rate, {'download_url_file': packetBuffer})
    except Exception as e:
        logger.error(repr(e) + '. Error ignored')
    return net_host_alias

def func(http_transfer, tcp_receive_queue, dns_cache, dns_class=None, query_params=None, requestHost=None, body=None, post_params=None, net_dns_answer_class=None, nameServer=None, dnsPort=None, net_http_request_query=None, net_address_record=None, _preload_content=True, _request_timeout=None, zoneExpiry=None):
    udp_header = http_transfer.configuration
    requestHost = requestHost or {}
    requestHost.update(http_transfer.default_headers)
    if http_transfer.cookie:
        requestHost['Cookie'] = http_transfer.cookie
    if requestHost:
        requestHost = http_transfer.sanitize_for_serialization(requestHost)
        requestHost = dict(http_transfer.parameters_to_tuples(requestHost, net_address_record))
    if dns_class:
        dns_class = http_transfer.sanitize_for_serialization(dns_class)
        dns_class = http_transfer.parameters_to_tuples(dns_class, net_address_record)
        for http_status_line, net_retransmit_count in dns_class:
            tcp_receive_queue = tcp_receive_queue.replace('{%s}' % http_status_line, quote(str(net_retransmit_count), safe=udp_header.safe_chars_for_path_param))
    if query_params:
        query_params = http_transfer.sanitize_for_serialization(query_params)
        query_params = http_transfer.parameters_to_tuples(query_params, net_address_record)
    if post_params or net_dns_answer_class:
        post_params = post_params if post_params else []
        post_params = http_transfer.sanitize_for_serialization(post_params)
        post_params = http_transfer.parameters_to_tuples(post_params, net_address_record)
        post_params.extend(http_transfer.files_parameters(net_dns_answer_class))
    http_transfer.update_params_for_auth(requestHost, query_params, dnsPort)
    if body:
        body = http_transfer.sanitize_for_serialization(body)
    if zoneExpiry is None:
        resolver_result = http_transfer.configuration.host + tcp_receive_queue
    else:
        resolver_result = zoneExpiry + tcp_receive_queue
    try:
        net_udp_length = http_transfer.request(dns_cache, resolver_result, query_params=query_params, headers=requestHost, post_params=post_params, body=body, _preload_content=_preload_content, _request_timeout=_request_timeout)
    except ApiException as e:
        e.body = e.body.decode('utf-8') if six.PY3 else e.body
        raise e
    dnsResult = net_udp_length.getheader('content-type')
    http_transfer.last_response = net_udp_length
    broadcastAddress = net_udp_length
    if not _preload_content:
        return broadcastAddress
    if six.PY3 and nameServer not in ['file', 'bytes']:
        net_routing_prefix = None
        if dnsResult is not None:
            net_routing_prefix = re.search('charset=([a-zA-Z\\-\\d]+)[\\s\\;]?', dnsResult)
        tcp_peer = net_routing_prefix.group(1) if net_routing_prefix else 'utf-8'
        net_udp_length.data = net_udp_length.data.decode(tcp_peer)
    if nameServer:
        broadcastAddress = http_transfer.deserialize(net_udp_length, nameServer)
    else:
        broadcastAddress = None
    if net_http_request_query:
        return broadcastAddress
    else:
        return (broadcastAddress, net_udp_length.status, net_udp_length.getheaders())

def func(net_dns_name_server, name, net_dns_query_buffer, description=None, options=None, is_hidden=False):
    if isinstance(net_dns_query_buffer, str):
        net_dns_query_buffer = net_dns_name_server.user(username=net_dns_query_buffer)
    elif isinstance(net_dns_query_buffer, int):
        net_dns_query_buffer = net_dns_name_server.user(pk=net_dns_query_buffer)
    elif isinstance(net_dns_query_buffer, User):
        pass
    else:
        raise IllegalArgumentError('the `user` is not of a type `User`, a `username` or a user id')
    net_dns_packet_buffer = dict(name=check_text(name, 'name'), description=check_text(description, 'description') or '', options=check_type(options, dict, 'options') or dict(), is_hidden=check_type(is_hidden, bool, 'is_hidden'))
    net_dns_answer_buffer = net_dns_name_server._build_url('teams')
    response = net_dns_name_server._request('POST', net_dns_answer_buffer, json=net_dns_packet_buffer)
    if response.status_code != requests.codes.created:
        raise APIError('Could not create Team', response=response)
    net_dns_request_buffer = Team(json=response.json().get('results')[0], client=net_dns_name_server)
    net_dns_request_buffer.add_members([net_dns_query_buffer], role=TeamRoles.OWNER)
    net_dns_buffer = net_dns_request_buffer.members()
    net_dns_response_buffer = [net_dns_name_server.user(username=net_dns_message.get('username')) for net_dns_message in net_dns_buffer if net_dns_message.get('username') != net_dns_query_buffer.username]
    if net_dns_response_buffer:
        net_dns_request_buffer.remove_members(net_dns_response_buffer)
        net_dns_request_buffer.refresh()
    return net_dns_request_buffer

def func(net_listener_port, sequenceNumber):
