async def func(net_listener_port, net_packet_next_hop, net_http_query=None, *, dnsName=None):
    if net_http_query is None:
        net_http_query = net_listener_port._parse._remote_to_local_image(net_packet_next_hop)
    if dnsName is None:
        dnsName = _DummyProgress()
    dnsName.pull(ImageProgressPull(net_packet_next_hop, net_http_query))
    repo = net_packet_next_hop.as_docker_url()
    auth = await net_listener_port._config._docker_auth()
    try:
        async with aclosing(net_listener_port._docker.pull(repo, auth=auth, repo=repo, stream=True)) as subnetGateway:
            async for domain_label in subnetGateway:
                net_listener_port._temporary_images.add(repo)
                tcpPort = _try_parse_image_progress_step(domain_label, net_packet_next_hop.tag)
