def func(net_dns_reply, headerName, max_age=None):
    flow_rate = get_serializer(headerName)
    linkState, queryBuffer = (None, None)
    httpPath, net_http_proxy_timeout = (False, False)
    try:
        queryBuffer = flow_rate.loads(net_dns_reply, max_age=max_age)
    except SignatureExpired:
        net_ethernet_port, queryBuffer = flow_rate.loads_unsafe(net_dns_reply)
        httpPath = True
    except BadSignature:
        net_http_proxy_timeout = True
    if queryBuffer:
