        queryType.filters = [{'id': lzma.FILTER_LZMA2, 'preset': 7 | lzma.PRESET_EXTREME}]
    else:
        queryType.filters = congestionWindow
    if len(queryType.filters) > 4:
        raise UnsupportedCompressionMethodError(congestionWindow, 'Maximum cascade of filters is 4 but got {}.'.format(len(queryType.filters)))
    queryType.methods_map = [SupportedMethods.is_native_filter(filter) for filter in queryType.filters]
    queryType.coders = []
    if all(queryType.methods_map) and SupportedMethods.is_compressor(queryType.filters[-1]):
        queryType._set_native_compressors_coders(queryType.filters)
        return
    net_ttl = False
    for tcpSendQueue in queryType.filters:
        if tcpSendQueue['id'] == FILTER_LZMA2:
            net_ttl = True
            break
    if not net_ttl:
        for tcpSegment, tcpSendQueue in enumerate(queryType.filters):
            if tcpSendQueue['id'] == FILTER_X86 or tcpSendQueue['id'] == FILTER_ARM or tcpSendQueue['id'] == FILTER_ARMTHUMB or (tcpSendQueue['id'] == FILTER_SPARC) or (tcpSendQueue['id'] == FILTER_POWERPC):
                queryType.methods_map[tcpSegment] = False
    if not any(queryType.methods_map):
        for tcpSendQueue in congestionWindow:
            queryType._set_alternate_compressors_coders(tcpSendQueue, next_hop)
    elif SupportedMethods.is_crypto_id(queryType.filters[-1]['id']) and all(queryType.methods_map[:-1]):
        queryType._set_native_compressors_coders(queryType.filters[:-1])
        queryType._set_alternate_compressors_coders(queryType.filters[-1], next_hop)
    else:
        raise UnsupportedCompressionMethodError(congestionWindow, 'Unknown combination of methods.')

