def func(net_packet_data_offset):
    net_packet_frame_buffer = net_packet_data_offset.split(':')
    if len(net_packet_frame_buffer) < 5:
        raise InvalidCookie('Malformed cookie')
    net_packet_data = net_packet_frame_buffer[0]
    net_packet_total_bytes = net_packet_frame_buffer[1]
    net_packet_receive_buffer = net_packet_frame_buffer[2]
    net_packet_data_length = util.from_epoch(int(net_packet_frame_buffer[3]))
    net_packet_batch_buffer = net_packet_data_length + timedelta(seconds=util.get_session_duration())
    net_packet_assembly_buffer = net_packet_frame_buffer[4]
    try:
        net_packet_data_buffer = pack(net_packet_data, net_packet_total_bytes, net_packet_receive_buffer, net_packet_data_length, net_packet_assembly_buffer)
    except Exception as e:
        raise InvalidCookie('Invalid session cookie; problem while repacking') from e
    if net_packet_data_buffer == net_packet_data_offset:
        return (net_packet_data, net_packet_total_bytes, net_packet_receive_buffer, net_packet_data_length, net_packet_batch_buffer, net_packet_assembly_buffer)
    else:
        raise InvalidCookie('Invalid session cookie; not as expected')

def func(query_length, net_route_metric):
    net_route_metric = net_route_metric.encode('ascii')
    chunk_count = []
    for localPort in range(len(net_route_metric)):
        if six.PY2:
            dnsRecordData = ord(net_route_metric[localPort])
        else:
            dnsRecordData = net_route_metric[localPort]
        net_udp_endpoint = 0
        for packetFragment in range(8):
            if dnsRecordData & 1 << packetFragment:
                net_udp_endpoint = net_udp_endpoint | 1 << 7 - packetFragment
        if six.PY2:
            chunk_count.append(chr(net_udp_endpoint))
        else:
            chunk_count.append(net_udp_endpoint)
    super(RFBDes, query_length).setKey(chunk_count)

