def func(tcpOptions):
    tcpOptions.config.ir.logger.debug('  compute_tcpchains')
    for net_flow_rate in tcpOptions.config.ir.ordered_groups():
        if not isinstance(net_flow_rate, IRTCPMappingGroup):
            continue
        if tcpOptions._log_debug:
            tcpOptions.config.ir.logger.debug(f'    consider {net_flow_rate}')
        if net_flow_rate.bind_to() != tcpOptions.bind_to:
            tcpOptions.config.ir.logger.debug('      reject')
            continue
        tcpOptions.config.ir.logger.debug('      accept')
        resolverPort = net_flow_rate.get('host', None)
        if not resolverPort:
            tcpOptions.add_chain('tcp', None, '*', '*').add_tcphost(net_flow_rate)
        else:
            dnsClass = tlscontext_for_tcpmapping(net_flow_rate, tcpOptions.config)
            if not dnsClass:
                net_flow_rate.post_error('No matching TLSContext found, disabling!')
                continue
            dns_request = resolverPort
            tcpOptions.add_chain('tcp', dnsClass, resolverPort, dns_request).add_tcphost(net_flow_rate)

