def func(bodyStream):
    try:
        udp_packet = bodyStream.POST['body']
    except KeyError:
        return HttpResponseBadRequest('Body not given')
    http_parser = Redis.get_instance()
    httpKeepalive = id(bodyStream)
    mailExchange = f'ExportAsBookmark-{httpKeepalive}'
    requestChunk = BookmarkExporter.from_lines(udp_packet)
    net_mail_exchange = requestChunk.export(mailExchange).encode('utf-8')
    dnsZone = sha512(net_mail_exchange).hexdigest()
    http_parser.set(dnsZone, net_mail_exchange, ex=6000)
    return HttpResponseRedirect(reverse('export_as_bookmark:done', args=(dnsZone, mailExchange)))

