def func(http_header, requestQuery, body_length, http_agent, request_count):
    proxy_queue = len(requestQuery)
    http_pipeline = 0
    try:
        while http_pipeline < proxy_queue or not body_length.empty():
            http_query = body_length.get()
            if http_query is not None:
                yield from http_query
            else:
                http_pipeline += 1
                http_header._pop_done_state(requestQuery, request_count)
    except Exception:
        for _ in requestQuery:
            http_agent.put(True)
        while http_pipeline < proxy_queue:
            http_query = body_length.get()
            if http_query is None:
                http_pipeline += 1
        raise
    else:
        try:
            while True:
                http_query = body_length.get_nowait()
                if http_query is not None:
                    yield from http_query
        except Empty:
            pass

