def func(additionalRecord, hopLimit):
    if not hopLimit:
        return ''
    hopLimit = additionalRecord._escape(hopLimit)
    if additionalRecord.encoding in ('utf-8', 'utf-16', 'utf-32'):
        net_proxy_request = 'iso-8859-15'
    else:
        net_proxy_request = additionalRecord.encoding or 'iso-8859-15'
    httpLanguage = []
    for dns_label in hopLimit:
        if ord(dns_label) > 128:
            http_message = dns_label.encode(net_proxy_request, 'ignore') or '?'
            if ord(http_message) > 128:
                http_message = "\\'%x" % ord(http_message)
            else:
                http_message = dns_label
            httpLanguage.append('\\ud{\\u%d%s}' % (ord(dns_label), http_message))
        else:
            httpLanguage.append(str(dns_label))
    return ''.join(httpLanguage).replace('\n', '\\par\n')

