def func(router=None, http_path=None):
    if router is None:
        router = []
    def access_decorator(net_http_length):
        @wraps(net_http_length)
        def decorated_function(*net_chunk_offset, **tcpBuffer):
            client_port = http_path
            if client_port is None:
                client_port = request.endpoint
            elif client_port.startswith('.'):
                client_port = request.endpoint[:request.endpoint.rindex('.')] + client_port
            if g.user.role in router:
                return net_http_length(*net_chunk_offset, **tcpBuffer)
            g.log.warning(f'attempt to access protected endpoint {request.endpoint} without required rights')
            abort(403, request.endpoint)
        return decorated_function
    return access_decorator

