def func(*chunkSize):
    http_version = set()
    proxyTimeout = {}
    http_stream = set()
    http_stream.update(chunkSize)
    while http_stream:
        next_hop_index = http_stream.pop()
        if next_hop_index in http_version:
            continue
        header_line = ()
        if next_hop_index == -2:
            header_line = (-1,)
        elif next_hop_index == -1:
            pass
        elif next_hop_index < 0:
            raise ValueError(f'bad {next_hop_index}')
        elif next_hop_index in (0, 1, 2, 3):
            pass
        elif next_hop_index == 4:
            header_line = (-2, 3)
        elif next_hop_index % 2 == 0:
            response_chunk = (next_hop_index - 2) // 2
            header_line = (response_chunk + 1, response_chunk + 3, response_chunk, response_chunk - 1, response_chunk + 2)
        else:
            response_chunk = (next_hop_index - 1) // 2
            if response_chunk % 2 == 0:
                header_line = (-2, response_chunk + 2, response_chunk, response_chunk - 1, response_chunk + 1)
            else:
                header_line = (response_chunk + 2, response_chunk, -2, response_chunk - 1, response_chunk + 1)
        if header_line:
            http_stream.update(header_line)
        proxyTimeout[next_hop_index] = header_line
        http_version.add(next_hop_index)
    return proxyTimeout

