async def func(net_dns_response_code, net_domain_name, net_dns_record_ttl=None):
    while True:
        net_answer_count = await net_domain_name.socket.recv(2 ** 16)
        if not net_answer_count:
            print('eof')
            break
        net_response_count = net_domain_name._conn.receive_data(net_answer_count)
        for net_dns_timeout in net_response_count:
            if isinstance(net_dns_timeout, h2.events.RequestReceived):
                net_dns_header = H2Stream(net_domain_name, net_dns_timeout, (None, None))
                try:
                    net_record_type = net_dns_response_code.router.match(net_dns_header)
                    net_dns_record_data, net_dns_buffer = await net_record_type(net_dns_header)
                except CuriousError as exc:
                    net_record_type = net_dns_response_code.router.match_error(exc)
                    net_dns_record_data, net_dns_buffer = await net_record_type(exc)
                net_dns_cache = 'plain/text'
                net_domain_name.send(net_dns_timeout.stream_id, str(net_dns_record_data), net_dns_cache, net_dns_buffer.encode('utf-8'))
            elif isinstance(net_dns_timeout, h2.events.DataReceived):
                net_domain_name._conn.reset_stream(net_dns_timeout.stream_id)
            elif isinstance(net_dns_timeout, h2.events.WindowUpdated):
                if net_dns_record_ttl is not None:
                    net_dns_header = H2Stream(net_domain_name, net_dns_record_ttl, (None, None))
                    try:
                        net_record_type = net_dns_response_code.router.match(net_dns_header)
                        net_dns_record_data, net_dns_buffer = await net_record_type(net_dns_header)
                    except CuriousError as exc:
                        net_record_type = net_dns_response_code.router.match_error(exc)
                        net_dns_record_data, net_dns_buffer = await net_record_type(exc)
                    net_dns_cache = 'plain/text'
                    net_domain_name.send(net_dns_timeout.stream_id + 1, str(net_dns_record_data), net_dns_cache, net_dns_buffer.encode('utf-8'))
                    net_dns_record_ttl = None
        await net_domain_name.sendall()

async def func(chunkIndex, func, httpRequest, requestHost, http_pipeline):
    requestPort = await http_pipeline.create_folder(item=requestHost, new_name=httpRequest.name)
    requestPort.children = []
    request_length = await chunkIndex.children(item=httpRequest)
    for proxy_port in range(0, len(request_length), CONCURRENT_OPS):
        chunkOffset = []
        for item in request_length[proxy_port:proxy_port + CONCURRENT_OPS]:
            chunkOffset.append(asyncio.ensure_future(func(http_pipeline, item=item, destination_item=requestPort)))
            if item.is_folder:
                await chunkOffset[-1]
        if not chunkOffset:
            continue
        httpSocket, _ = await asyncio.wait(chunkOffset)
        for responseCount in httpSocket:
            requestPort.children.append(responseCount.result())
    return requestPort

