async def func(queryParameter, response_index, *, httpStatusCode=None, http_header_count=None, httpStatusLine=False, statusLine=None, reasonPhrase=None, content_disposition=None, responseIndex=None, strict_mode=True):
    issues = {}
    if response_index is None and httpStatusLine is False:
        raise ValidationError(queryParameter.ERROR_NOT_NULLABLE)
    if response_index is None:
        return response_index
    if not isinstance(response_index, Sequence) or isinstance(response_index, str):
        raise ValidationError(queryParameter.ERROR_BAD_TYPE.format('array'))
    if statusLine is not None:
        if len(response_index) < statusLine:
            raise ValidationError(queryParameter.ERROR_MIN_LENGTH.format(statusLine))
    if reasonPhrase is not None:
        if len(response_index) > reasonPhrase:
            raise ValidationError(queryParameter.ERROR_MAX_LENGTH.format(reasonPhrase))
    if content_disposition is not None:
        responseChunk = set(response_index) - set(content_disposition)
        if responseChunk:
            raise ValidationError(queryParameter.ERROR_UNALLOWED_VALUES.format(list(responseChunk)))
    if httpStatusCode is not None:
        for httpStatus in range(0, len(response_index)):
            try:
                response_index[httpStatus] = await queryParameter.validate(response_index[httpStatus], **httpStatusCode, strict_mode=strict_mode)
            except ValidationError as e:
                issues[httpStatus] = e.msg if e.issues is None else e.issues
    if len(issues.keys()):
        raise ValidationError(queryParameter.ERROR_ARRAY_ITEMS, issues=issues)
    return response_index

