def func(net_proxy_timeout, net_http_path, net_reason_phrase, net_request_count):
    if not isinstance(net_http_path, KspArray):
        raise TypeError(f'arr has to be instance of {KspArray}')
    net_proxy_timeout.__vars = list()
    net_http_response_time = 0
    for net_content_type in net_reason_phrase:
        if isinstance(net_content_type, (int, str, float)):
            net_http_path[net_http_response_time + net_request_count] <<= net_content_type
            net_proxy_timeout.__vars.append(net_http_path[net_http_response_time + net_request_count])
            net_http_response_time += 1
            continue
        if not isinstance(net_content_type, (KspVar, kLoc)):
            raise TypeError('all variables has to be instance of ' + f'{(KspVar, kLoc, int, str, float)}. ' + f'Type of {net_content_type} is {type(net_content_type)}')
        if isinstance(net_content_type, kLoc):
            if net_content_type._size > 1:
                net_proxy_timeout.__vars.append(StackFrameArray(net_http_path, net_http_response_time + net_request_count, net_http_response_time + net_request_count + net_content_type._size))
                with For(net_content_type._size) as net_http_content_length:
                    for net_header_value in net_http_content_length:
                        net_http_path[net_header_value + net_http_response_time + net_request_count] <<= net_http_path.default
                    net_http_response_time += net_content_type._size
            else:
                net_http_path[net_http_response_time + net_request_count] <<= net_http_path.default
                net_proxy_timeout.__vars.append(net_http_path[net_http_response_time + net_request_count])
                net_http_response_time += 1
            continue
        if isinstance(net_content_type, KspArray):
            net_proxy_timeout.__vars.append(StackFrameArray(net_http_path, net_http_response_time + net_request_count, net_http_response_time + net_request_count + len(net_content_type)))
            with For(len(net_content_type)) as net_http_content_length:
                for net_header_value in net_http_content_length:
                    net_proxy_timeout.__vars[-1][net_header_value] = net_content_type[net_header_value]
                    net_http_response_time += 1
            continue
        net_http_path[net_http_response_time + net_request_count] <<= net_content_type
        net_proxy_timeout.__vars.append(net_http_path[net_http_response_time + net_request_count])
        net_http_response_time += 1
    net_proxy_timeout.__size = net_http_response_time

def func(http_request, content_length=True):
    if http_request._done:
        raise RuntimeError('cannot run training loop multiple times')
    try:
        os.makedirs(http_request.out)
    except OSError:
        pass
    responseReason = sorted(http_request._extensions.keys(), key=lambda headerCount: http_request._extensions[headerCount].priority, reverse=True)
    http_version = [(headerCount, http_request._extensions[headerCount]) for headerCount in responseReason]
    http_request._start_at = _get_time()
    for _, http_header in http_version:
        statusCode = getattr(http_header.extension, 'initialize', None)
        request_url = getattr(http_header.trigger, 'finished', False)
        if statusCode and (not request_url):
            statusCode(http_request)
    urlPort = http_request.updater.update
    request_length = http_request.reporter
    http_host = http_request.stop_trigger
    try:
        while not http_host(http_request):
            http_request.observation = {}
            with request_length.scope(http_request.observation):
                urlPort()
                for headerCount, http_header in http_version:
                    if http_header.trigger(http_request):
                        http_header.extension(http_request)
    except Exception as e:
        if content_length:
            header_line = sys.stderr
            header_line.write('Exception in main training loop: {}\n'.format(e))
            header_line.write('Traceback (most recent call last):\n')
            traceback.print_tb(sys.exc_info()[2])
            header_line.write('Will finalize trainer extensions and updater before reraising the exception.\n')
        response_chunk = sys.exc_info()
        for _, http_header in http_version:
            httpResponseTime = getattr(http_header.extension, 'on_error', None)
            if httpResponseTime:
                try:
                    httpResponseTime(http_request, e, sys.exc_info()[2])
                except Exception as he:
                    header_line.write('Exception in error handler: {}\n'.format(he))
                    header_line.write('Traceback (most recent call last):\n')
                    traceback.print_tb(sys.exc_info()[2])
        six.reraise(*response_chunk)
    finally:
        for _, http_header in http_version:
            headerField = getattr(http_header.extension, 'finalize', None)
            if headerField:
                headerField()
        http_request.updater.finalize()
    http_request._final_elapsed_time = http_request.elapsed_time
    http_request._done = True

