def func(serverAddress, congestionState):
    if congestionState:
        serverAddress.update_count(congestionState)
    else:
        serverAddress.update_valid_canbe(congestionState)
    dnsCache, subnetPrefix = (False, False)
    acknowledgementNumber, host_address = (False, False)
    dns_count, net_route_destination = (False, False)
    for route_prefix in colors:
        proxyAddress = len(serverAddress.bot.game.playedCards[route_prefix]) + 1
        for send_buffer in serverAddress.bot.values:
            if serverAddress.cantBe[route_prefix][send_buffer]:
                continue
            if send_buffer < proxyAddress:
                subnetPrefix = True
                host_address = True
                dns_count = True
            elif send_buffer == proxyAddress:
                dnsCache = True
                if not acknowledgementNumber or not host_address:
                    http_body = maxCards[send_buffer]
                    if serverAddress.bot.botPlayedCount[route_prefix][send_buffer] == http_body - 1:
                        acknowledgementNumber = True
                    else:
                        host_address = True
                net_route_destination = True
            else:
                subnetPrefix = True
                if not acknowledgementNumber or not host_address:
                    if serverAddress.bot.isValuable(route_prefix, send_buffer):
                        acknowledgementNumber = True
                    else:
                        host_address = True
                if not dns_count or not net_route_destination:
                    if serverAddress.bot.isWorthless(route_prefix, send_buffer):
                        dns_count = True
                    else:
                        net_route_destination = True
        if dnsCache and acknowledgementNumber and dns_count:
            break
    assert dnsCache or subnetPrefix
    assert acknowledgementNumber or host_address
    assert dns_count or net_route_destination
    serverAddress.playable = (None if subnetPrefix else True) if dnsCache else False
    serverAddress.valuable = (None if host_address else True) if acknowledgementNumber else False
    serverAddress.worthless = (None if net_route_destination else True) if dns_count else False
    if serverAddress.worthless is True:
        assert serverAddress.valuable is False
        assert serverAddress.playable is False

