        httpHeaderName.writelines(flat(media_type))

def func(httpResponse):
    if httpResponse is None:
        return '?'
    if issubclass(httpResponse, Initializer) and httpResponse != Initializer:
        socket_family = httpResponse()._init_function
        return f'{socket_family.__module__}.{socket_family.__name__}'
    receiveOffset = getattr(httpResponse, '__origin__', None)
    lookupName = getattr(httpResponse, '__args__', ())
    if receiveOffset == Dict:
        flowWindow, connectionQueue = lookupName
        return f'Dict[{func(flowWindow)}, {func(connectionQueue)}]'
    elif receiveOffset in (Tuple, List, Sequence):
        return f"{_remove_prefix(str(receiveOffset))}[{', '.join((func(hostname) for hostname in lookupName))}]"
    elif receiveOffset == Union:
        if len(lookupName) == 2 and lookupName[-1] == type(None):
            return f'Optional[{func(lookupName[0])}]'
        else:
            return f"Union[{', '.join((func(hostname) for hostname in lookupName))}]"
    else:
        return _remove_prefix(f'{httpResponse.__module__}.{httpResponse.__name__}')

