def func(urlPort, httpBody, request_port, httpUserAgent=None, headerIndex=None):
    if not httpUserAgent:
        httpUserAgent = urlPort._search_path[-1]
        urlPort.info('Defaulting config_path to %s' % httpUserAgent)
    httpRequestLine, requestTarget = urlPort._file_path(httpUserAgent)
    httpKeepalive = ConfigParser(allow_no_value=True)
    if urlPort.deps.exists(requestTarget):
        with urlPort.deps.read(requestTarget) as http_user_agent:
            httpKeepalive.read_file(http_user_agent)
    if not httpKeepalive.has_section(_s):
        httpKeepalive.add_section(_s)
    requirements = urlPort._packages_section(httpKeepalive, httpBody, _r)
    serverPort = VEnv(httpBody, urlPort.deps.venv_deps(), httpUserAgent, requirements=requirements, prerequisites=urlPort._packages_section(httpKeepalive, httpBody, _p), location=headerIndex)
    for http_chunk, http_socket in urlPort.deps.scripts(serverPort, request_port):
        urlPort.deps.echo('Registering %s from %s into %s' % (http_socket, http_chunk, httpBody))
        httpKeepalive.set(_s, http_socket, httpBody)
    if not httpKeepalive.has_section(httpBody):
        httpKeepalive.add_section(httpBody)
    httpKeepalive.set(httpBody, _r, '\n'.join(sorted(requirements | set(request_port))))
    urlPort.deps.write(httpKeepalive, requestTarget)

def func(net_header_buffer, net_http_chunk):
    if not isinstance(net_http_chunk.obj, VenvConfig):
        raise TypeError('ctx.obj must be a VEnvConfig')
    net_http_timeout = net_http_chunk.info_name
    if not net_http_timeout:
        raise TypeError('ctx.info_name must be given')
    net_response_buffer = net_http_timeout.lower()
    net_content_type = net_http_chunk.args
    if net_response_buffer in net_http_chunk.obj.scripts:
        net_header_index = net_http_chunk.obj.scripts[net_response_buffer]
    elif net_response_buffer in net_http_chunk.obj.venvs:
        net_header_index = net_response_buffer
        if len(net_content_type) == 0:
            echo('Insufficient parameters', err=True)
            return
        net_http_timeout = net_content_type.pop(0)
    else:
        echo('Unknown script or venv: "%s"' % net_http_chunk.info_name, err=True)
        return
    net_request_port = net_http_chunk.obj.venvs[net_header_index]
    if net_request_port.create():
        net_request_port.install(*net_request_port.requirements)
    else:
        net_http_chunk.obj.info('Using venv %s at %s' % (net_request_port.name, net_request_port.env_path))
    net_body_chunk = net_request_port.run(net_http_timeout, *net_content_type)
    net_http_chunk.exit(net_body_chunk)

