def func(queryType):
    dnsRcode = 0
    while True:
        dns_record_type = hashlib.sha3_256(f'{dnsRcode} || {queryType}'.encode()).digest()
        httpUserAgent = int.from_bytes(dns_record_type, 'big') % bn128.field_modulus
        httpBody = sympy.sqrt_mod(httpUserAgent ** 3 + 3, bn128.field_modulus)
        if httpBody:
            assert httpBody ** 2 % bn128.field_modulus == (httpUserAgent ** 3 + 3) % bn128.field_modulus
            return _unwrap((bn128.FQ(httpUserAgent), bn128.FQ(httpBody)))
        dnsRcode += 1

