def func(status_line, httpKeepalive):
    http_chunk = utils.base58_decode(httpKeepalive)
    headerField = '{:x}'.format(http_chunk)
    httpSocket = headerField[-4 * 2:].decode('hex')
    http_proxy = headerField[:-4 * 2].decode('hex')
    responseTimeout = hashlib.sha256(http_proxy).digest()
    contentType = hashlib.sha256(responseTimeout).digest()
    if contentType[:4] != httpSocket:
        raise RuntimeError('Invalid checksum for the address.')
    return status_line(http_proxy[1:].encode('hex'))

