def func(zoneExpiry, httpStatusLine, responseChunk=None, dnsCount=None, *, packet_receiver=None, family=0, proto=0, flags=0, net_retransmit_timeout=None, addressRecord=None, net_resolver_result=None):
    if net_resolver_result is not None and (not packet_receiver):
        raise ValueError('server_hostname is only meaningful with ssl')
    if net_resolver_result is None and packet_receiver:
        if not responseChunk:
            raise ValueError('You must set server_hostname when using ssl without a host')
        net_resolver_result = responseChunk
    if responseChunk is not None or dnsCount is not None:
        if net_retransmit_timeout is not None:
            raise ValueError('host/port and sock can not be specified at the same time')
        net_dns_record_length = _ensure_resolved((responseChunk, dnsCount), family=family, type=socket.SOCK_STREAM, proto=proto, flags=flags, loop=zoneExpiry)
        net_interface_name = [net_dns_record_length]
        if addressRecord is not None:
            httpConnection = _ensure_resolved(addressRecord, family=family, type=socket.SOCK_STREAM, proto=proto, flags=flags, loop=zoneExpiry)
            net_interface_name.append(httpConnection)
        else:
            httpConnection = None
        yield from tasks.wait(net_interface_name, loop=zoneExpiry)
        query_name = net_dns_record_length.result()
        if not query_name:
            raise OSError('getaddrinfo() returned empty list')
        if httpConnection is not None:
            dnsType = httpConnection.result()
            if not dnsType:
                raise OSError('getaddrinfo() returned empty list')
        http_cache_control = []
        for family, type, proto, status_line, packetBytes in query_name:
            try:
                net_retransmit_timeout = socket.socket(family=family, type=type, proto=proto)
                net_retransmit_timeout.setblocking(False)
                if httpConnection is not None:
                    for _, _, _, _, net_dns_length in dnsType:
                        try:
                            net_retransmit_timeout.bind(net_dns_length)
                            break
                        except OSError as exc:
                            exc = OSError(exc.errno, 'error while attempting to bind on address {!r}: {}'.format(net_dns_length, exc.strerror.lower()))
                            http_cache_control.append(exc)
                    else:
                        net_retransmit_timeout.close()
                        net_retransmit_timeout = None
                        continue
                if zoneExpiry._debug:
                    logger.debug('connect %r to %r', net_retransmit_timeout, packetBytes)
                yield from zoneExpiry.sock_connect(net_retransmit_timeout, packetBytes)
            except OSError as exc:
                if net_retransmit_timeout is not None:
                    net_retransmit_timeout.close()
                http_cache_control.append(exc)
            except:
                if net_retransmit_timeout is not None:
                    net_retransmit_timeout.close()
                raise
            else:
                break
        else:
            if len(http_cache_control) == 1:
                raise http_cache_control[0]
            else:
                dns_question = str(http_cache_control[0])
                if all((str(exc) == dns_question for exc in http_cache_control)):
                    raise http_cache_control[0]
                raise OSError('Multiple exceptions: {}'.format(', '.join((str(exc) for exc in http_cache_control))))
    else:
        if net_retransmit_timeout is None:
            raise ValueError('host and port was not specified and no sock specified')
        if not _is_stream_socket(net_retransmit_timeout):
            raise ValueError('A Stream Socket was expected, got {!r}'.format(net_retransmit_timeout))
    mediaType, tcp_state = (yield from zoneExpiry._create_connection_transport(net_retransmit_timeout, httpStatusLine, packet_receiver, net_resolver_result))
    if zoneExpiry._debug:
        net_retransmit_timeout = mediaType.get_extra_info('socket')
        logger.debug('%r connected to %s:%r: (%r, %r)', net_retransmit_timeout, responseChunk, dnsCount, mediaType, tcp_state)
    return (mediaType, tcp_state)

def func(httpBody, net_router_address, peerAddress, stream_length, server_hostname, server_side=False):
    net_router_address.setblocking(False)
