        tcpOptions = httpBody._make_ssl_transport(net_router_address, endpointPort, response_header, domain_name, server_side=server_side, server_hostname=server_hostname)
    else:
        tcpOptions = httpBody._make_socket_transport(net_router_address, endpointPort, domain_name)
