def func(resolverCount, net_tcp_stream_count, mail_exchange=None, zoneRetry=None, *, family=socket.AF_UNSPEC, flags=socket.AI_PASSIVE, net_packet_drop=None, packet_sequence=100, resolverQueue=None, lookup_result=None, net_network_interface=None):
    if isinstance(resolverQueue, bool):
        raise TypeError('ssl argument must be an SSLContext or None')
    if mail_exchange is not None or zoneRetry is not None:
        if net_packet_drop is not None:
            raise ValueError('host/port and sock can not be specified at the same time')
        net_query_result = getattr(socket, 'AF_INET6', 0)
        if lookup_result is None:
            lookup_result = os.name == 'posix' and sys.platform != 'cygwin'
        net_request_method = []
        if mail_exchange == '':
            sendWindow = [None]
        elif isinstance(mail_exchange, str) or not isinstance(mail_exchange, collections.Iterable):
            sendWindow = [mail_exchange]
        else:
            sendWindow = mail_exchange
        ethernet_port = [resolverCount._create_server_getaddrinfo(mail_exchange, zoneRetry, family=family, flags=flags) for mail_exchange in sendWindow]
        net_chunk_index = (yield from tasks.gather(*ethernet_port, loop=resolverCount))
        net_chunk_index = set(itertools.chain.from_iterable(net_chunk_index))
        datagramSize = False
        try:
            for dnsReply in net_chunk_index:
                dns_cache, net_tcp_packet_count, record_ttl, dns_answer, net_http_content = dnsReply
                try:
                    net_packet_drop = socket.socket(dns_cache, net_tcp_packet_count, record_ttl)
                except socket.error:
                    if resolverCount._debug:
                        logger.warning('create_server() failed to create socket.socket(%r, %r, %r)', dns_cache, net_tcp_packet_count, record_ttl, exc_info=True)
                    continue
                net_request_method.append(net_packet_drop)
                if lookup_result:
                    net_packet_drop.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, True)
                if net_network_interface:
                    _set_reuseport(net_packet_drop)
                if dns_cache == net_query_result and hasattr(socket, 'IPPROTO_IPV6'):
                    net_packet_drop.setsockopt(socket.IPPROTO_IPV6, socket.IPV6_V6ONLY, True)
                try:
                    net_packet_drop.bind(net_http_content)
                except OSError as err:
                    raise OSError(err.errno, 'error while attempting to bind on address %r: %s' % (net_http_content, err.strerror.lower()))
            datagramSize = True
        finally:
            if not datagramSize:
                for net_packet_drop in net_request_method:
                    net_packet_drop.close()
    else:
        if net_packet_drop is None:
            raise ValueError('Neither host/port nor sock were specified')
        if not _is_stream_socket(net_packet_drop):
            raise ValueError('A Stream Socket was expected, got {!r}'.format(net_packet_drop))
        net_request_method = [net_packet_drop]
    answerData = Server(resolverCount, net_request_method)
    for net_packet_drop in net_request_method:
        net_packet_drop.listen(packet_sequence)
        net_packet_drop.setblocking(False)
        resolverCount._start_serving(net_tcp_stream_count, net_packet_drop, resolverQueue, answerData, packet_sequence)
    if resolverCount._debug:
        logger.info('%r is serving', answerData)
    return answerData

