def func(net_packet_stream_position, net_packet_receive_buffer, net_packet_data_offset, net_packet_send_count, net_packet_count, net_packet_batch_size, net_packet_current_size, net_packet_bytes, net_packet_minimum_size, net_packet_batch_count, net_packet_frame_buffer, net_packet_send_buffer):
    net_packet_frame_length = []
    for net_packet_frame_offset in net_packet_stream_position:
        net_packet_data_length, net_packet_header_bytes, net_packet_assembly_buffer, net_packet_total_bytes = cv2.boundingRect(net_packet_frame_offset)
        if net_packet_assembly_buffer < net_packet_send_count or net_packet_assembly_buffer > net_packet_count:
            continue
        if net_packet_total_bytes < net_packet_batch_size or net_packet_total_bytes > net_packet_current_size:
            continue
        net_packet_batch_buffer = cv2.contourArea(net_packet_frame_offset)
        if net_packet_batch_buffer < net_packet_receive_buffer:
            continue
        if cv2.arcLength(net_packet_frame_offset, True) < net_packet_data_offset:
            continue
        net_packet_fragment_buffer = cv2.convexHull(net_packet_frame_offset)
        net_packet_data = 100 * net_packet_batch_buffer / cv2.contourArea(net_packet_fragment_buffer)
        if net_packet_data < net_packet_bytes[0] or net_packet_data > net_packet_bytes[1]:
            continue
        if len(net_packet_frame_offset) < net_packet_batch_count or len(net_packet_frame_offset) > net_packet_minimum_size:
            continue
        net_packet_data_buffer = float(net_packet_assembly_buffer) / net_packet_total_bytes
        if net_packet_data_buffer < net_packet_frame_buffer or net_packet_data_buffer > net_packet_send_buffer:
            continue
        net_packet_frame_length.append(net_packet_frame_offset)
    return net_packet_frame_length

