def func(udpIndex, udp_queue, connection_index):
    if connection_index == 1:
        return udp_queue
    if connection_index == -1:
        retransmitQueue = -udp_queue
        if retransmitQueue >= 2 ** 31 - 1:
            return 2 ** 31 - 1
        else:
            return retransmitQueue
    if udp_queue < 0:
        stream_length = -udp_queue
    else:
        stream_length = udp_queue
    if connection_index < 0:
        udpSocket = -connection_index
    else:
        udpSocket = connection_index
    def func(stream_length, udpSocket):
        if stream_length < udpSocket:
            return 0
        tcp_throughput = udpSocket
        retransmitQueue = 1
        while stream_length >= tcp_throughput << 1:
            tcp_throughput <<= 1
            retransmitQueue <<= 1
        return func(stream_length - tcp_throughput, udpSocket) + retransmitQueue
    retransmitQueue = func(stream_length, udpSocket)
    if udp_queue > 0 and connection_index > 0 or (udp_queue < 0 and connection_index < 0):
        return retransmitQueue
    else:
        return -retransmitQueue

def func(listener_port):
    tcp_segment = PARSER.parse_args(listener_port)
    tcpPeer = tcp_segment.dst
    assert tcpPeer.suffix == '.hash'
    tcp_options = tcpPeer.parent
    if tcp_options.name != '.hash':
        if tcp_segment.debug:
            print(f'Invalid name {tcpPeer} -> dirname {tcp_options}', file=sys.stderr)
        return 0
    tcp_options.mkdir(exist_ok=True)
    tcpBuffer = tcp_options.parent
    tcpConnection = tcpPeer.stem
    udp_index = tcpBuffer / tcpConnection
    socket_address = hashlib.sha256()
    try:
        socket_address.update(udp_index.read_bytes())
    except OSError:
        if tcp_segment.debug:
            print(f'Cannot open {udp_index}', file=sys.stderr)
        return 0
    socket_option = socket_address.hexdigest()
    if tcpPeer.exists():
        udpPacket = tcpPeer.read_text()
    else:
        udpPacket = ''
    if socket_option != udpPacket:
        tcpPeer.write_text(socket_option)
        print(f're-hash {socket_option}')
    elif tcp_segment.debug:
        print(f'Skip {socket_option} checksum, up-to-date')
    return 0

def func(socket_option, sendBuffer, udpPeer, retransmitTimeout, tcpRetransmit):
    if len(sendBuffer) > 1:
        raise TypeError('{} takes at most 1 positional argument ({} given)'.format(retransmitTimeout, len(sendBuffer)))
    if sendBuffer:
        tcp_delay = sendBuffer[0]
        if isinstance(sendBuffer[0], (MultiDict, MultiDictProxy)) and (not udpPeer):
            endpoint_address = tcp_delay._impl._items
        else:
            if hasattr(tcp_delay, 'items'):
                tcp_delay = tcp_delay.items()
            if udpPeer:
                tcp_delay = list(tcp_delay)
                tcp_delay.extend(list(udpPeer.items()))
            endpoint_address = []
            for tcp_port in tcp_delay:
                if not len(tcp_port) == 2:
                    raise TypeError('{} takes either dict or list of (key, value) tuples'.format(retransmitTimeout))
                endpoint_address.append((socket_option._title(tcp_port[0]), socket_option._key(tcp_port[0]), tcp_port[1]))
        tcpRetransmit(endpoint_address)
    else:
        tcpRetransmit([(socket_option._title(send_queue), socket_option._key(send_queue), listener_socket) for send_queue, listener_socket in udpPeer.items()])

def func(httpSocket, request_query):
    if not request_query:
        return
    headerValue = {}
    for server_port, server_address, request_queue in request_query:
        serverPort = headerValue.get(server_port, 0)
        for httpRange in range(serverPort, len(httpSocket._impl._items)):
            httpPort = httpSocket._impl._items[httpRange]
            if httpPort[0] == server_port:
                headerValue[server_port] = httpRange + 1
                httpSocket._impl._items[httpRange] = (server_port, server_address, request_queue)
                break
        else:
            httpSocket._impl._items.append((server_port, server_address, request_queue))
            headerValue[server_port] = len(httpSocket._impl._items)
    httpRange = 0
    while httpRange < len(httpSocket._impl._items):
        httpPort = httpSocket._impl._items[httpRange]
        server_port = httpPort[0]
        httpLength = headerValue.get(server_port)
        if httpLength is None:
            httpRange += 1
            continue
        if httpRange >= httpLength:
            del httpSocket._impl._items[httpRange]
        else:
            httpRange += 1
    httpSocket._impl.incr_version()

