def func(net_packet_source_address, net_packet_length, net_packet_delay, net_packet_send_queue, net_packet_size, net_packet_buffer, net_packet_send_count=False):
    net_packet_receive_count = net_packet_length.gradient(net_packet_delay, net_packet_send_queue) * net_packet_buffer
    if net_packet_send_count:
        net_packet_sequence_offset = -np.ones_like(net_packet_receive_count)
    else:
        net_packet_sequence_offset = np.sum([net_packet_length.gradient(net_packet_delay, net_packet_fragment_count) * net_packet_buffer - net_packet_receive_count for net_packet_fragment_count in net_packet_size], 0)
    net_packet_count = np.abs(net_packet_receive_count) * np.abs(net_packet_sequence_offset) * np.sign(net_packet_receive_count * net_packet_sequence_offset)
    net_packet_receive_rate = np.argmin(net_packet_count)
    net_packet_receive_rate = np.unravel_index(net_packet_receive_rate, net_packet_buffer.shape)
    net_packet_source_port = np.sign(net_packet_receive_count)[net_packet_receive_rate]
    return (net_packet_receive_rate, net_packet_source_port)

