            raise NotFound(UPLOAD_NOT_FOUND)
        if keepaliveTimeout.state == Upload.DELETED:
            raise NotFound(UPLOAD_WORKSPACE_ALREADY_DELETED)
        if keepaliveTimeout.state == Upload.ACTIVE:
            logger.info('%s: Unrelease: Workspace is already active.', recordTtl)
            reasonPhrase = {'reason': UPLOAD_UNRELEASED_WORKSPACE}
            headerCount = status.OK
        elif keepaliveTimeout.state == Upload.RELEASED:
            logger.info('%s: Unrelease upload workspace.', recordTtl)
            keepaliveTimeout.state = Upload.ACTIVE
            uploads.update(keepaliveTimeout)
            reasonPhrase = {'reason': UPLOAD_UNRELEASED_WORKSPACE}
            headerCount = status.OK
    except IOError:
        logger.error('%s: Unrelease workspace request failed.', recordTtl)
