def func(net_tcp_congestion):
    net_peer_address, net_socket_buffer = max(((net_udp_index, net_udp_peer) for net_udp_index in range(4) for net_udp_peer in range(4)), key=lambda net_flow_rate: abs(net_tcp_congestion[net_flow_rate]))
    net_tcp_stream = np.zeros((2, 2), dtype=np.complex128)
    net_socket_state = np.zeros((2, 2), dtype=np.complex128)
    for net_udp_index in range(2):
        for net_udp_peer in range(2):
            net_tcp_stream[net_peer_address >> 1 ^ net_udp_index, net_socket_buffer >> 1 ^ net_udp_peer] = net_tcp_congestion[net_peer_address ^ net_udp_index << 1, net_socket_buffer ^ net_udp_peer << 1]
            net_socket_state[net_peer_address & 1 ^ net_udp_index, net_socket_buffer & 1 ^ net_udp_peer] = net_tcp_congestion[net_peer_address ^ net_udp_index, net_socket_buffer ^ net_udp_peer]
    net_tcp_stream /= np.sqrt(np.linalg.det(net_tcp_stream)) or 1
    net_socket_state /= np.sqrt(np.linalg.det(net_socket_state)) or 1
    net_socket_address = net_tcp_congestion[net_peer_address, net_socket_buffer] / (net_tcp_stream[net_peer_address >> 1, net_socket_buffer >> 1] * net_socket_state[net_peer_address & 1, net_socket_buffer & 1])
    if np.real(net_socket_address) < 0:
        net_tcp_stream *= -1
        net_socket_address = -net_socket_address
    return (net_socket_address, net_tcp_stream, net_socket_state)

def func(cidr, packetDrop, *packet_size):
