def func(router_interface, route_prefix, packetAddress, networkAddress, forwardingEntry, packetFragment, next_hop):
    packetDelay = route_prefix.shape[0]
    next_hop_address = 2 * packetFragment / (next_hop ** 2 + EPS)
    packet_header = np.sign(packetFragment) * np.inf
    packetReceiver = next_hop_address
    packet_queue = 0
    while True:
        packet_queue += 1
        packetLength = 0
        packet = 0
        if packetFragment > 0:
            for router_config in range(packetDelay):
                packet_data = packetReceiver * packetAddress[router_config] / 2
                if packetAddress[router_config] > 0:
                    router_port = forwardingEntry - route_prefix[router_config]
                    subnet_mask = min(router_port, packet_data)
                    packetLength += packetAddress[router_config] * subnet_mask
                    packet += subnet_mask ** 2
                else:
                    router_port = networkAddress - route_prefix[router_config]
                    subnet_mask = max(router_port, packet_data)
                    packetLength += packetAddress[router_config] * subnet_mask
                    packet += subnet_mask ** 2
        else:
            for router_config in range(packetDelay):
                packet_data = packetReceiver * packetAddress[router_config] / 2
                if packetAddress[router_config] > 0:
                    router_port = networkAddress - route_prefix[router_config]
                    subnet_mask = max(router_port, packet_data)
                    packetLength += packetAddress[router_config] * subnet_mask
                    packet += subnet_mask ** 2
                else:
                    router_port = forwardingEntry - route_prefix[router_config]
                    subnet_mask = min(router_port, packet_data)
                    packetLength += packetAddress[router_config] * subnet_mask
                    packet += subnet_mask ** 2
        if np.abs(packetLength) < np.abs(packetFragment):
            if np.isinf(packet_header):
                packetReceiver *= 2
            else:
                next_hop_address = packetReceiver
                packetReceiver = (packet_header - next_hop_address) / 2 + next_hop_address
        else:
            packet_header = packetReceiver
            packetReceiver = (packet_header - next_hop_address) / 2 + next_hop_address
        if 0.999 * np.abs(packetFragment) - EPS < np.abs(packetLength) < 1.001 * np.abs(packetFragment) + EPS:
            break
    return np.sqrt(packet)

def func(net_packet_header_bytes, net_packet_receive_timestamp, net_packet_window_offset, net_packet_byte_offset, net_packet_fragment_count, net_packet_route_entry, net_packet_header_offset, net_packet_receive_count, net_packet_frame_offset):
    net_packet_receiver_address, net_packet_flow_rate = net_packet_receive_timestamp
    net_packet_data = net_packet_window_offset.shape[0]
    net_packet_assembly_buffer = 0
    net_packet_source = 0
    net_packet_bytes = 0
    if net_packet_flow_rate > 0:
        for net_packet_size in range(net_packet_data):
            net_packet_channel_index = net_packet_window_offset[net_packet_size] - net_packet_byte_offset[net_packet_size]
            net_packet_delay = net_packet_fragment_count[net_packet_size]
            net_packet_arrival_time = 1 / (2 * net_packet_flow_rate + EPS)
            net_packet_fragment_size = -net_packet_receiver_address * net_packet_delay * net_packet_arrival_time - net_packet_channel_index
            if np.abs(net_packet_fragment_size) - net_packet_arrival_time < 0:
                net_packet_queue = net_packet_channel_index
            else:
                net_packet_queue = np.sign(net_packet_fragment_size) * (np.abs(net_packet_fragment_size) - net_packet_arrival_time) + net_packet_channel_index
                if net_packet_queue + net_packet_byte_offset[net_packet_size] < net_packet_route_entry:
                    net_packet_queue = net_packet_route_entry - net_packet_byte_offset[net_packet_size]
                elif net_packet_queue + net_packet_byte_offset[net_packet_size] > net_packet_header_offset:
                    net_packet_queue = net_packet_header_offset - net_packet_byte_offset[net_packet_size]
                else:
                    net_packet_current_size = np.sign(net_packet_queue - net_packet_channel_index) + 2 * net_packet_flow_rate * net_packet_queue + net_packet_receiver_address * net_packet_delay
                    net_packet_source -= net_packet_current_size * net_packet_delay * net_packet_arrival_time
                    net_packet_bytes -= net_packet_current_size * 2 * net_packet_queue * net_packet_arrival_time
            net_packet_assembly_buffer += np.abs(net_packet_channel_index - net_packet_queue) + net_packet_flow_rate * net_packet_queue ** 2 + net_packet_receiver_address * net_packet_delay * net_packet_queue
            net_packet_source += net_packet_delay * net_packet_queue
            net_packet_bytes += net_packet_queue ** 2
    else:
        for net_packet_size in range(net_packet_data):
            net_packet_channel_index = net_packet_window_offset[net_packet_size] - net_packet_byte_offset[net_packet_size]
            net_packet_delay = net_packet_fragment_count[net_packet_size]
            if np.abs(net_packet_receiver_address * net_packet_delay) < 1:
                net_packet_queue = net_packet_channel_index
            elif np.sign(net_packet_receiver_address * net_packet_delay) < 0:
                net_packet_queue = net_packet_header_offset - net_packet_byte_offset[net_packet_size]
            else:
                net_packet_queue = net_packet_route_entry - net_packet_byte_offset[net_packet_size]
            net_packet_assembly_buffer += np.abs(net_packet_channel_index - net_packet_queue) + net_packet_flow_rate * net_packet_queue ** 2 + net_packet_receiver_address * net_packet_delay * net_packet_queue
            net_packet_source += net_packet_delay * net_packet_queue
            net_packet_bytes += net_packet_queue ** 2
    net_packet_assembly_buffer += -net_packet_flow_rate * net_packet_frame_offset ** 2 - net_packet_receiver_address * net_packet_receive_count
    net_packet_source -= net_packet_receive_count
    net_packet_bytes -= net_packet_frame_offset ** 2
    return (-net_packet_assembly_buffer, -np.array([net_packet_source, net_packet_bytes]))

