def func(datagram_queue, routePriority, hopCount):
    if datagram_queue.get('ANGLE') == 0.0 and datagram_queue.get('B') is not None:
        routeCache = datagram_queue['B'] / routePriority.brho
        datagram_queue['ANGLE'] = datagram_queue['L'] * routeCache
    if datagram_queue['ANGLE'] == 0.0:
        network_interface = 0 * _ureg.tesla
    else:
        network_interface = routePriority.brho / (datagram_queue['L'] / _np.abs(datagram_queue['ANGLE']))
    if _np.isnan(datagram_queue['E1']):
        route_prefix = 0.0 * _ureg.radian
    else:
        route_prefix = datagram_queue['E1']
    if _np.isnan(datagram_queue['E2']):
        packetIndex = 0.0 * _ureg.radian
    else:
        packetIndex = datagram_queue['E2']
    if _np.isnan(datagram_queue['TILT']):
        datagram_length = 0.0 * _ureg.radian
    else:
        datagram_length = datagram_queue['TILT']
    if hopCount.get('command', Bend) == Bend:
        datagram_size = Bend(datagram_queue.name[0:_ZGOUBI_LABEL_LENGTH], XL=datagram_queue['L'], B1=network_interface, KPOS=3, W_E=route_prefix * _np.sign(datagram_queue['ANGLE']), W_S=packetIndex * _np.sign(datagram_queue['ANGLE']), KINEMATICS=routePriority, LENGTH_IS_ARC_LENGTH=hopCount.get('LENGTH_IS_ARC_LENGTH', True))
    elif hopCount.get('command') == Dipole:
        if datagram_queue.N is not None and (not _np.isnan(datagram_queue.N)):
            link_state = datagram_queue.N
        elif datagram_queue.K1 is not None and (not _np.isnan(datagram_queue.K1)):
            link_state = -(_np.abs(datagram_queue.L / datagram_queue.ANGLE).to('m') ** 2 * getattr(datagram_queue, 'K1', 0.0 * _ureg.m ** (-2))).magnitude
        else:
            link_state = 0
        datagram_size = Dipole(datagram_queue.name[0:_ZGOUBI_LABEL_LENGTH], RM=_np.abs(datagram_queue.L / datagram_queue.ANGLE), AT=_np.abs(datagram_queue.ANGLE), B0=network_interface, N=link_state)
    if datagram_queue['TILT'] != 0:
        datagram_size.COLOR = 'goldenrod'
    if datagram_queue['ANGLE'] < 0:
        return [ChangeRef(datagram_queue.name + '_CRL', TRANSFORMATIONS=[['XR', -(-datagram_length + _np.pi * _ureg.radian)]]), datagram_size, ChangeRef(datagram_queue.name + '_CRR', TRANSFORMATIONS=[['XR', -datagram_length + _np.pi * _ureg.radian]])]
    elif _np.isnan(datagram_queue['TILT']) or datagram_queue['TILT'] == 0:
        return [datagram_size]
    else:
        return [ChangeRef(datagram_queue.name + '_CRL', TRANSFORMATIONS=[['XR', datagram_length]]), datagram_size, ChangeRef(datagram_queue.name + '_CRR', TRANSFORMATIONS=[['XR', -datagram_length]])]

