def func(http_client, response_index):
    proxy_host, proxy_port = (-1, -1)
    for http_length, (_, proxy_timeout) in response_index.iter(http_client):
        httpConnection = http_length + 1 - len(proxy_timeout)
        if proxy_host < 0:
            proxy_host, proxy_port = (httpConnection, http_length)
        elif httpConnection <= proxy_port + 1:
            proxy_port = http_length
        else:
            yield (proxy_host, proxy_port + 1)
            proxy_host, proxy_port = (httpConnection, http_length)
    if proxy_host >= 0:
        yield (proxy_host, proxy_port + 1)

