def func(urlPath, queryClass, socketOption=''):
    if socketOption not in ['', 'chromium', 'firefox']:
        raise ValueError('Invalid bogus keyword value')
    urlPath._app_id = queryClass
    dns_cache_timeout = {'typ': 'navigator.id.finishEnrollment', 'challenge': base64.b64encode(_random_32()).decode('utf-8'), 'origin': queryClass}
    dns_class = hashlib.sha256()
    dns_class.update(json.dumps(dns_cache_timeout).encode('utf-8'))
    urlPath._challenge_parameter = dns_class.digest()
    if socketOption == 'chromium':
        urlPath._app_parameter = b'A' * 32
    elif socketOption == 'firefox':
        urlPath._app_parameter = b'\x00' * 32
    else:
        net_dns_label = hashlib.sha256()
        net_dns_label.update(queryClass.encode('utf-8'))
        urlPath._app_parameter = net_dns_label.digest()
    httpBuffer = bytearray(64)
    for ttl in range(0, 32):
        httpBuffer[ttl] = urlPath._challenge_parameter[ttl]
    for ttl in range(0, 32):
        httpBuffer[32 + ttl] = urlPath._app_parameter[ttl]
    urlPath._apdu = APDU(U2F_REGISTER, 0, 0, len(httpBuffer), httpBuffer)

