def func(request_length, status_code=403, net_pointer_record=None):
    requestIndex = [request_length] if isinstance(request_length, str) else list(request_length)
    def decorator(func):
        net_upstream_address = inspect.signature(func)
        for net_content_range, dns_name in enumerate(net_upstream_address.parameters.values()):
            if dns_name.name == 'request' or dns_name.name == 'websocket':
                requestPort = dns_name.name
                break
        else:
            raise Exception(f'No "request" or "websocket" argument on function "{func}"')
        if requestPort == 'websocket':
            @functools.wraps(func)
            async def websocket_wrapper(*retransmitTimeout, **net_route_path):
                net_tcp_keepalive_interval = net_route_path.get('websocket', retransmitTimeout[net_content_range] if net_content_range < len(retransmitTimeout) else None)
                assert isinstance(net_tcp_keepalive_interval, WebSocket)
                if not has_required_scope(net_tcp_keepalive_interval, requestIndex):
                    await net_tcp_keepalive_interval.close()
                else:
                    await func(*retransmitTimeout, **net_route_path)
            return websocket_wrapper
        elif is_async_callable(func):
            @functools.wraps(func)
            async def async_wrapper(*retransmitTimeout, **net_route_path):
                network_frame = net_route_path.get('request', retransmitTimeout[net_content_range] if net_content_range < len(retransmitTimeout) else None)
                assert isinstance(network_frame, Request)
                if not has_required_scope(network_frame, requestIndex):
                    if net_pointer_record is not None:
                        answerRecord = urlencode({'next': str(network_frame.url)})
                        responseBody = f'{network_frame.url_for(net_pointer_record)}?{answerRecord}'
                        return RedirectResponse(url=responseBody, status_code=303)
                    raise HTTPException(status_code=status_code)
                return await func(*retransmitTimeout, **net_route_path)
            return async_wrapper
        else:
            @functools.wraps(func)
            def sync_wrapper(*retransmitTimeout, **net_route_path):
                network_frame = net_route_path.get('request', retransmitTimeout[net_content_range] if net_content_range < len(retransmitTimeout) else None)
                assert isinstance(network_frame, Request)
                if not has_required_scope(network_frame, requestIndex):
                    if net_pointer_record is not None:
                        answerRecord = urlencode({'next': str(network_frame.url)})
                        responseBody = f'{network_frame.url_for(net_pointer_record)}?{answerRecord}'
                        return RedirectResponse(url=responseBody, status_code=303)
                    raise HTTPException(status_code=status_code)
                return func(*retransmitTimeout, **net_route_path)
            return sync_wrapper
    return decorator

