        return tcp_listener.session_class()
    retransmit_timeout = udpPeer.config['SESSION_CRYPTO_KEY'] if 'SESSION_CRYPTO_KEY' in udpPeer.config else udpPeer.crypto_key
    tcpCongestion = sendLength.split('.')
    if len(tcpCongestion) != 4:
        return tcp_listener.session_class()
    try:
        if tcpCongestion[0] == 'z':
            tcpQueue = True
        else:
            tcpQueue = False
        round_trip_time = base64.b64decode(bytes(tcpCongestion[1], 'utf-8'))
        tcp_send_buffer = base64.b64decode(bytes(tcpCongestion[2], 'utf-8'))
        localPort = base64.b64decode(bytes(tcpCongestion[3], 'utf-8'))
        udp_count = AES.new(retransmit_timeout, AES.MODE_EAX, localPort)
        tcp_receive_buffer = udp_count.decrypt_and_verify(round_trip_time, tcp_send_buffer)
        if tcpQueue:
            tcp_receive_buffer = zlib.decompress(tcp_receive_buffer)
        socket_connection = pickle.loads(tcp_receive_buffer)
        return tcp_listener.session_class(socket_connection)
    except (ValueError, _pickle.UnpicklingError, pickle.UnpicklingError, AttributeError, ModuleNotFoundError):
        return tcp_listener.session_class()

