def func(interface_name, responseIndex):
    receive_queue = 0
    interface_name._fields_ = set()
    net_query_string = sorted(interface_name._field_map.items(), key=lambda net_http_response_reason: len(net_http_response_reason[0].mro()))
    for net_address_record, net_http_stream in interface_name.__dict__.get('_layout_', {}).items():
        if net_address_record not in interface_name.__annotations__:
            raise ValueError('{} is not annotated'.format(net_address_record))
        streamCount = interface_name.__annotations__[net_address_record]
        for field_type, addressRecord in net_query_string:
            if issubclass(streamCount, field_type):
                net_http_length = addressRecord(net_http_stream, field_type=streamCount)
                if hasattr(net_http_length, '__set_name__'):
                    net_http_length.__set_name__(interface_name, net_address_record)
                setattr(interface_name, net_address_record, net_http_length)
                interface_name._fields_.add(net_address_record)
                if hasattr(net_http_length, '_end_of_field'):
                    receive_queue = max(receive_queue, net_http_length._end_of_field)
                break
        else:
            raise ValueError('{} is not registered'.format(streamCount.__name__))
    if responseIndex is not None:
        interface_name._size_ = responseIndex
    if interface_name._size_ == 0:
        interface_name._size_ = receive_queue
    if interface_name._size_ < receive_queue:
        raise ValueError('Size of {} must be larger then {} bytes'.format(interface_name.__name__, receive_queue))

