def func(router_queue, net_mtu):
    net_url_port = []
    httpPath = int(router_queue.y - router_queue.radius)
    tcp_listener = int(router_queue.y + router_queue.radius)
    for http_message in range(httpPath, tcp_listener + 1):
        net_socket_type = 0
        if http_message < router_queue.y:
            if http_message == httpPath:
                net_socket_type = math.pi / 2
            else:
                net_socket_type = math.asin((router_queue.y - http_message) / router_queue.radius)
        if http_message > router_queue.y:
            if http_message == tcp_listener:
                net_socket_type = math.pi / 2
            else:
                net_socket_type = math.asin((http_message - router_queue.y) / router_queue.radius)
        response_count = int(math.cos(net_socket_type) * router_queue.radius)
        httpPath = router_queue.x - response_count
        tcp_listener = router_queue.x + response_count
        for proxyRequest in range(httpPath, tcp_listener + 1):
            net_url_port.append(net_mtu[http_message * router_queue.img_width + proxyRequest])
    return net_url_port

