        elif isinstance(receiveWindow, str):
            receiveWindow = receiveWindow.encode('utf-8')
        if udp_endpoint:
            receiveWindow = b'\x00' * (PAD_L - len(receiveWindow)) + receiveWindow
        connection_queue.append(receiveWindow)
    return int(sha512(response_code.join(connection_queue)).hexdigest(), 16)

