    connectionAttempt.attempted_config_files.append(udpPort)
    socket_endpoint = HandyConfigParser(receiveQueue)
    try:
        slowStartThreshold = socket_endpoint.read(udpPort)
    except configparser.Error as err:
        raise CoverageException("Couldn't read config file %s: %s" % (udpPort, err))
    if not slowStartThreshold:
        return False
    connectionAttempt.config_files.extend(slowStartThreshold)
    try:
        for socketHandle in connectionAttempt.CONFIG_FILE_OPTIONS:
            connectionAttempt._set_attr_from_config_option(socket_endpoint, *socketHandle)
    except ValueError as err:
        raise CoverageException("Couldn't read config file %s: %s" % (udpPort, err))
    tcpPort = collections.defaultdict(set)
    for socketHandle in connectionAttempt.CONFIG_FILE_OPTIONS:
        roundTripDelay, udp_index = socketHandle[1].split(':')
        tcpPort[roundTripDelay].add(udp_index)
    for roundTripDelay, send_length in iitems(tcpPort):
        if socket_endpoint.has_section(roundTripDelay):
            for connectionIndex in set(socket_endpoint.options(roundTripDelay)) - send_length:
                if receiveQueue:
                    roundTripDelay = receiveQueue + roundTripDelay
                raise CoverageException("Unrecognized option '[%s] %s=' in config file %s" % (roundTripDelay, connectionIndex, udpPort))
    if socket_endpoint.has_section('paths'):
        for udp_index in socket_endpoint.options('paths'):
            connectionAttempt.paths[udp_index] = socket_endpoint.getlist('paths', udp_index)
    for socket_backlog in connectionAttempt.plugins:
        if socket_endpoint.has_section(socket_backlog):
            connectionAttempt.plugin_options[socket_backlog] = socket_endpoint.get_section(socket_backlog)
    return True

def func(request_host, dnsResponseCode, hostAlias, format, domainLabel='graphviz'):
    domainRecord = hostAlias.get('graphviz_dot', request_host.builder.config.graphviz_dot)
    lookup_result = (dnsResponseCode + str(hostAlias) + str(domainRecord) + str(request_host.builder.config.graphviz_dot_args)).encode('utf-8')
    resolverAddress = '%s-%s.%s' % (domainLabel, sha1(lookup_result).hexdigest(), format)
    hostname = posixpath.join(request_host.builder.imgpath, resolverAddress)
    answer_record = path.join(request_host.builder.outdir, request_host.builder.imagedir, resolverAddress)
    if path.isfile(answer_record):
        return (hostname, answer_record)
    if hasattr(request_host.builder, '_graphviz_warned_dot') and request_host.builder._graphviz_warned_dot.get(domainRecord):
        return (None, None)
    ensuredir(path.dirname(answer_record))
    if isinstance(dnsResponseCode, text_type):
        dnsResponseCode = dnsResponseCode.encode('utf-8')
    response_count = [domainRecord]
    response_count.extend(request_host.builder.config.graphviz_dot_args)
    response_count.extend(['-T' + format, '-o' + answer_record])
    record_class = hostAlias.get('docname', 'index')
    cwd = path.dirname(path.join(request_host.builder.srcdir, record_class))
    if format == 'png':
        response_count.extend(['-Tcmapx', '-o%s.map' % answer_record])
    try:
        http_referer = Popen(response_count, stdout=PIPE, stdin=PIPE, stderr=PIPE, cwd=cwd)
    except OSError as err:
        if err.errno != ENOENT:
            raise
        logger.warning(__('dot command %r cannot be run (needed for graphviz output), check the graphviz_dot setting'), domainRecord)
        if not hasattr(request_host.builder, '_graphviz_warned_dot'):
            request_host.builder._graphviz_warned_dot = {}
        request_host.builder._graphviz_warned_dot[domainRecord] = True
        return (None, None)
    try:
        stdout, stderr = http_referer.communicate(dnsResponseCode)
    except (OSError, IOError) as err:
        if err.errno not in (EPIPE, EINVAL):
            raise
        stdout, stderr = (http_referer.stdout.read(), http_referer.stderr.read())
        http_referer.wait()
    if http_referer.returncode != 0:
        raise GraphvizError(__('dot exited with error:\n[stderr]\n%s\n[stdout]\n%s') % (stderr, stdout))
    if not path.isfile(answer_record):
        raise GraphvizError(__('dot did not produce an output file:\n[stderr]\n%s\n[stdout]\n%s') % (stderr, stdout))
    return (hostname, answer_record)

def func(net_tcp_connection_index, net_tcp_buffer):
    net_tcp_packet_buffer = net_tcp_connection_index.builder.config.imgmath_image_format.lower()
    if net_tcp_packet_buffer not in SUPPORT_FORMAT:
        raise MathExtError('imgmath_image_format must be either "png" or "svg"')
    net_tcp_segment_buffer = generate_latex_macro(net_tcp_buffer, net_tcp_connection_index.builder.config)
    net_tcp_packet_count = '%s.%s' % (sha1(net_tcp_segment_buffer.encode('utf-8')).hexdigest(), net_tcp_packet_buffer)
    net_tcp_send_bytes = posixpath.join(net_tcp_connection_index.builder.imgpath, 'math', net_tcp_packet_count)
    net_tcp_send_buffer = path.join(net_tcp_connection_index.builder.outdir, net_tcp_connection_index.builder.imagedir, 'math', net_tcp_packet_count)
    if path.isfile(net_tcp_send_buffer):
        net_tcp_receive_buffer = read_png_depth(net_tcp_send_buffer)
        return (net_tcp_send_bytes, net_tcp_receive_buffer)
    if hasattr(net_tcp_connection_index.builder, '_imgmath_warned_latex') or hasattr(net_tcp_connection_index.builder, '_imgmath_warned_image_translator'):
        return (None, None)
    try:
        net_tcp_sent_bytes = compile_math(net_tcp_segment_buffer, net_tcp_connection_index.builder)
    except InvokeError:
        net_tcp_connection_index.builder._imgmath_warned_latex = True
        return (None, None)
    try:
        if net_tcp_packet_buffer == 'png':
            net_tcp_received_bytes, net_tcp_receive_buffer = convert_dvi_to_png(net_tcp_sent_bytes, net_tcp_connection_index.builder)
        elif net_tcp_packet_buffer == 'svg':
            net_tcp_received_bytes, net_tcp_receive_buffer = convert_dvi_to_svg(net_tcp_sent_bytes, net_tcp_connection_index.builder)
    except InvokeError:
        net_tcp_connection_index.builder._imgmath_warned_image_translator = True
        return (None, None)
    ensuredir(path.dirname(net_tcp_send_buffer))
    shutil.move(net_tcp_received_bytes, net_tcp_send_buffer)
    return (net_tcp_send_bytes, net_tcp_receive_buffer)

def func(http_proxy, bodyStream):
    try:
        dnsAnswer = os.path.basename(bodyStream['uri'])
        if '?' in dnsAnswer:
            dnsAnswer = dnsAnswer.split('?')[0]
        if dnsAnswer == '' or len(dnsAnswer) > MAX_FILENAME_LEN:
            net_http_port, upstreamAddress = os.path.splitext(bodyStream['uri'])
            dnsAnswer = sha1(net_http_port.encode('utf-8')).hexdigest() + upstreamAddress
        net_zone_transfer = bodyStream['uri'].replace('://', '/').translate({ord('?'): u'/', ord('&'): u'/'})
        if len(net_zone_transfer) > MAX_FILENAME_LEN:
            net_zone_transfer = sha1(net_zone_transfer.encode('utf-8')).hexdigest()
        ensuredir(os.path.join(http_proxy.imagedir, net_zone_transfer))
        net_tcp_ack = os.path.join(http_proxy.imagedir, net_zone_transfer, dnsAnswer)
        headers = {}
        if os.path.exists(net_tcp_ack):
            contentRange = ceil(os.stat(net_tcp_ack).st_mtime)
            headers['If-Modified-Since'] = epoch_to_rfc1123(contentRange)
        request_body = requests.get(bodyStream['uri'], headers=headers)
        if request_body.status_code >= 400:
            logger.warning(__('Could not fetch remote image: %s [%d]') % (bodyStream['uri'], request_body.status_code))
        else:
            http_proxy.app.env.original_image_uri[net_tcp_ack] = bodyStream['uri']
            if request_body.status_code == 200:
                with open(net_tcp_ack, 'wb') as streamBuffer:
                    streamBuffer.write(request_body.content)
            dnsCacheSize = request_body.headers.get('last-modified')
            if dnsCacheSize:
                contentRange = rfc1123_to_epoch(dnsCacheSize)
                os.utime(net_tcp_ack, (contentRange, contentRange))
            net_zone_serial = guess_mimetype(net_tcp_ack, default='*')
            if net_zone_serial != '*' and os.path.splitext(dnsAnswer)[1] == '':
                upstreamAddress = get_image_extension(net_zone_serial)
                retransmissionTimer = os.path.join(http_proxy.imagedir, net_zone_transfer, dnsAnswer + upstreamAddress)
                movefile(net_tcp_ack, retransmissionTimer)
                http_proxy.app.env.original_image_uri.pop(net_tcp_ack)
                http_proxy.app.env.original_image_uri[retransmissionTimer] = bodyStream['uri']
                net_tcp_ack = retransmissionTimer
            bodyStream['candidates'].pop('?')
            bodyStream['candidates'][net_zone_serial] = net_tcp_ack
            bodyStream['uri'] = net_tcp_ack
            http_proxy.app.env.images.add_file(http_proxy.env.docname, net_tcp_ack)
    except Exception as exc:
        logger.warning(__('Could not fetch remote image: %s [%s]') % (bodyStream['uri'], text_type(exc)))

