def func(dnsPointer, dnsCache):
    routingEntry = set()
    nameServer = set()
    resolverAddress = dnsPointer._updates
    dns_record_data = dnsPointer._expunges
    resolverQueue = dnsPointer._mod_seqs_order
    dnsCacheEntry = len(resolverQueue)
    dnsResponse = bisect_left(resolverQueue, dnsCache, 0, dnsCacheEntry)
    for domain_resolver in islice(resolverQueue, dnsResponse, dnsCacheEntry):
        dnsPacket = resolverAddress.get(domain_resolver)
        answerRecord = dns_record_data.get(domain_resolver)
        if dnsPacket is not None:
            routingEntry.update(dnsPacket)
        if answerRecord is not None:
            nameServer.update(answerRecord)
    return (frozenset(routingEntry), frozenset(nameServer))

async def func(net_tcp_retransmit_count, query_buffer):
    query_length = 0
    try:
        resolverQueue = await net_tcp_retransmit_count._exec(query_buffer.do_greeting())
    except ResponseError as exc:
        net_tcp_socket_family = exc.get_response(b'*')
        net_tcp_socket_family.condition = ResponseBye.condition
        await net_tcp_retransmit_count.write_response(net_tcp_socket_family)
        return
    else:
        await net_tcp_retransmit_count.write_response(resolverQueue)
    while True:
        try:
            net_tcp_flow_rate = await net_tcp_retransmit_count.read_command(query_buffer)
        except (ConnectionError, EOFError):
            break
        except CancelledError:
            await net_tcp_retransmit_count.send_error_disconnect()
            break
        except Exception:
            await net_tcp_retransmit_count.send_error_disconnect()
            raise
        else:
            lookupResult = current_command.set(net_tcp_flow_rate)
            try:
                if isinstance(net_tcp_flow_rate, AuthenticateCommand):
                    resolver_port = await net_tcp_retransmit_count.authenticate(query_buffer, net_tcp_flow_rate.mech_name)
                    queryClass = await net_tcp_retransmit_count._exec(query_buffer.do_authenticate(net_tcp_flow_rate, resolver_port))
                elif isinstance(net_tcp_flow_rate, IdleCommand):
                    queryClass = await net_tcp_retransmit_count.idle(query_buffer, net_tcp_flow_rate)
                else:
                    queryClass = await net_tcp_retransmit_count._exec(query_buffer.do_command(net_tcp_flow_rate))
            except ResponseError as exc:
                net_tcp_socket_family = exc.get_response(net_tcp_flow_rate.tag)
                await net_tcp_retransmit_count.write_response(net_tcp_socket_family)
                if net_tcp_socket_family.is_terminal:
                    break
            except AuthenticationError as exc:
                query_type = bytes(str(exc), 'utf-8', 'surrogateescape')
                net_tcp_socket_family = ResponseBad(net_tcp_flow_rate.tag, query_type)
                await net_tcp_retransmit_count.write_response(net_tcp_socket_family)
            except TimeoutError:
                net_tcp_socket_family = ResponseNo(net_tcp_flow_rate.tag, b'Operation timed out.', ResponseCode.of(b'TIMEOUT'))
                await net_tcp_retransmit_count.write_response(net_tcp_socket_family)
            except (CancelledError, ConnectionError, EOFError):
                await net_tcp_retransmit_count.send_error_disconnect()
                break
            except Exception:
                await net_tcp_retransmit_count.send_error_disconnect()
                raise
            else:
                await net_tcp_retransmit_count.write_response(queryClass)
                if queryClass.is_bad:
                    query_length += 1
                    if net_tcp_retransmit_count.bad_command_limit and query_length >= net_tcp_retransmit_count.bad_command_limit:
                        query_type = b'Too many errors, disconnecting.'
                        queryClass.add_untagged(ResponseBye(query_type))
                else:
                    query_length = 0
                if queryClass.is_terminal:
                    break
                if isinstance(net_tcp_flow_rate, StartTLSCommand) and isinstance(queryClass, ResponseOk):
                    try:
                        await net_tcp_retransmit_count.start_tls()
                    except ConnectionError:
                        break
                    except SSLError as exc:
                        net_tcp_retransmit_count._print('%s <->| <TLS failure: %s>', exc.reason)
                        return
            finally:
                await query_buffer.do_cleanup()
                current_command.reset(lookupResult)

