    try:
        headerIndex = jwt.decode(tcp_port, settings.SECRET_KEY, algorithm=['HS256'])
        socketState = headerIndex['userId']
        send_window = headerIndex['gradingId']
        if socketState is None or send_window is None:
            raise ValueError('Invalid Token')
    except Exception:
        raise ValueError('Invalid Token')
    net_dns_pointer_record = Grading.objects.get(pk=send_window)
    if net_dns_pointer_record.claimed_by.id != socketState:
        raise ValueError('Invalid Token')
    if net_dns_pointer_record.finish_at is not None:
        raise ValueError('You Have Submitted This Job')
    net_dns_pointer_record.finish_at = timezone.now()
    net_dns_pointer_record.verdict = udpPacket
    net_dns_pointer_record.output = socketAddress
    net_dns_pointer_record.save()
    grading_group = net_dns_pointer_record.grading_group
    retransmitQueue = grading_group.grading_size
    endpoint_address = Grading.objects.filter(grading_group=grading_group).all()
    net_dns_query_length = 0
    peerPort = 0
    tcpSequence = set()
    for net_dns_class in endpoint_address:
        if net_dns_class.finish_at is not None:
            peerPort += 1
        if net_dns_class.verdict == 'AC':
            net_dns_query_length += 1
        tcpSequence.add(net_dns_class.verdict)
    if peerPort == retransmitQueue:
        grading_group.finish_time = timezone.now()
        if net_dns_query_length >= (retransmitQueue + 1) // 2:
            grading_group.verdict = 'AC'
        else:
            udpHeader = ['RTE', 'MLE', 'TLE', 'WA', 'CE']
            socketTimeout = False
            for tcp_sequence in udpHeader:
                if tcp_sequence in tcpSequence:
                    grading_group.verdict = tcp_sequence
                    socketTimeout = True
                    break
            if not socketTimeout:
