        net_dns_answer_buffer = False
        if net_dns_datagram:
            net_dns_answer_buffer = True
        else:
            for net_dns_name_label in net_dns_opcode:
                if net_dns_name_label == net_dns_query_message:
                    net_dns_answer_buffer = True
            for net_dns_cache_entry in net_dns_response_code:
