def func(net_http_body=None, net_http_request_url=True, rootdir=CURDIR, **net_http_port):
    net_http_path = setup_parser()
    net_http_proxy_request = dict(((net_http_referer.dest, net_http_referer) for net_http_referer in net_http_path._actions))
    net_http_proxy_queue = net_http_path.parse_args(net_http_body or [])
    net_http_proxy_queue.file_params = {}
    net_http_proxy_queue.linters_params = {}
    if net_http_request_url:
        net_http_parser = get_config(net_http_proxy_queue.options, rootdir=rootdir)
        for net_http_keepalive, net_http_status_code in net_http_parser.default.items():
            LOGGER.info('Find option %s (%s)', net_http_keepalive, net_http_status_code)
            net_http_downstream_port = getattr(net_http_proxy_queue, net_http_keepalive, _Default())
            if isinstance(net_http_downstream_port, _Default):
                if net_http_keepalive == 'paths':
                    net_http_status_code = net_http_status_code.split()
                if net_http_keepalive == 'skip':
                    net_http_status_code = fix_pathname_sep(net_http_status_code)
                setattr(net_http_proxy_queue, net_http_keepalive, _Default(net_http_status_code))
        for net_http_chunk_offset, net_http_request_buffer in net_http_parser.sections.items():
            if net_http_chunk_offset == net_http_parser.default_section:
                continue
            if net_http_chunk_offset.startswith('pylama'):
                net_http_chunk_offset = net_http_chunk_offset[7:]
            if net_http_chunk_offset in LINTERS:
                net_http_proxy_queue.linters_params[net_http_chunk_offset] = dict(net_http_request_buffer)
                continue
            net_http_range = re.compile(fnmatch.translate(fix_pathname_sep(net_http_chunk_offset)))
            net_http_proxy_queue.file_params[net_http_range] = dict(net_http_request_buffer)
    for net_http_keepalive, net_http_status_code in net_http_port.items():
        setattr(net_http_proxy_queue, net_http_keepalive, process_value(net_http_proxy_request, net_http_keepalive, net_http_status_code))
    for net_http_chunk_offset in net_http_proxy_queue.__dict__:
        net_http_pipeline = getattr(net_http_proxy_queue, net_http_chunk_offset)
        if isinstance(net_http_pipeline, _Default):
            setattr(net_http_proxy_queue, net_http_chunk_offset, process_value(net_http_proxy_request, net_http_chunk_offset, net_http_pipeline.value))
    if net_http_proxy_queue.concurrent and 'pylint' in net_http_proxy_queue.linters:
        LOGGER.warning("Can't parse code asynchronously with pylint enabled.")
        net_http_proxy_queue.concurrent = False
    return net_http_proxy_queue

