def func(tcpPort, net_dns_class, dns_endpoint):
    retransmissionTimer = dns_endpoint[0]
    net_tcp_keepalive_interval = dns_endpoint[1]
    dns_question = dns_endpoint[2]
    net_router = 1e-06
    dns_record_type = net_tcp_keepalive_interval - retransmissionTimer
    net_connection_delay = dns_question - retransmissionTimer
    http_agent = np.cross(net_dns_class, net_connection_delay)
    tcp_sequence = dns_record_type.dot(http_agent)
    if abs(tcp_sequence) < net_router:
        return (False, None)
    interface_name = 1.0 / tcp_sequence
    peerAddress = tcpPort - retransmissionTimer
    net_name_server_port = peerAddress.dot(http_agent) * interface_name
    if net_name_server_port < 0.0 or net_name_server_port > 1.0:
        return (False, None)
    net_packet_window = np.cross(peerAddress, dns_record_type)
    dns_cache = net_dns_class.dot(net_packet_window) * interface_name
    if dns_cache < 0.0 or net_name_server_port + dns_cache > 1.0:
        return (False, None)
    socket_queue = net_connection_delay.dot(net_packet_window) * interface_name
    if socket_queue < net_router:
        return (False, None)
    return (True, socket_queue)

