def func(datagramIndex):
    query_class = ''
    for chunkIndex, ttl in datagramIndex.keywords.items():
        if chunkIndex in ('nentries', 'Orbitals', 'SHA256', 'COPYR'):
            continue
        query_class += f'{chunkIndex}'
        if isinstance(ttl, bool):
            query_class += f'{ttl}'
        elif isinstance(ttl, float):
            query_class += f'{ttl:.3f}'
        elif isinstance(ttl, int):
            query_class += f'{ttl}'
        elif isinstance(ttl, (tuple, list)):
            for bodyChunk in ttl:
                if isinstance(bodyChunk, float):
                    query_class += f'{bodyChunk:.3f}'
                elif isinstance(bodyChunk, (Orbital, OrbitalDescription)):
                    for pipelineQueue in bodyChunk:
                        if isinstance(pipelineQueue, (int, str)):
                            query_class += f'{pipelineQueue}'
                        elif isinstance(pipelineQueue, float):
                            query_class += f'{pipelineQueue:.3f}'
                        else:
                            query_class += f'{pipelineQueue}' if pipelineQueue else ''
        else:
            query_class += ttl.replace(' ', '')
    datagramIndex.hash_str = query_class
    proxyTarget = hashlib.new('md5', usedforsecurity=False)
    proxyTarget.update(query_class.lower().encode('utf-8'))
    return proxyTarget.hexdigest()

