def func(congestionControl):
    if not congestionControl.args.kwonlyargs:
        return congestionControl
    if congestionControl.args.kwarg:
        tcp_ack = congestionControl.args.kwarg.arg
    else:
        tcp_ack = 'kwargs'
        congestionControl.args.kwarg = ast.arg(arg=tcp_ack, annotation=None)
    tcp_socket = reversed(congestionControl.args.kwonlyargs)
    tcp_options = reversed(congestionControl.args.kw_defaults)
    for arg, receive_length in zip(tcp_socket, tcp_options):
        congestionWindow = arg.arg
        if receive_length is None:
            remotePort = ast.Subscript(value=ast.Name(id=tcp_ack, ctx=ast.Load()), slice=ast.Index(value=AstStr(s=congestionWindow)), ctx=ast.Load())
        elif not isinstance(receive_length, common.ConstantNodeTypes):
            socket_handle = f'Keyword only arguments must be immutable. Found: {receive_length} for {congestionWindow}'
            raise common.FixerError(socket_handle, congestionControl)
        else:
            remotePort = ast.Call(func=ast.Attribute(value=ast.Name(id=tcp_ack, ctx=ast.Load()), attr='get', ctx=ast.Load()), args=[AstStr(s=congestionWindow), receive_length], keywords=[])
        retransmission_timer = ast.Assign(targets=[ast.Name(id=congestionWindow, ctx=ast.Store())], value=remotePort)
        congestionControl.body.insert(0, retransmission_timer)
    congestionControl.args.kwonlyargs = []
    return congestionControl

