                raise ValueError(f"Invalid value '{retransmitTimeout}' for {tcp_keepalive.env_key}. Attepmted to parse '{tcp_window}.{tcp_keepalive.fname}' with '{tcp_keepalive.ftyp}'.", err)
        elif tcp_keepalive.fallback != __fallback_sentinel__:
            tcpHeader[tcp_keepalive.fname] = tcp_keepalive.fallback
        else:
            raise KeyError(f'No environment variable {tcp_keepalive.env_key} ' + f'found for field {tcp_window}.{tcp_keepalive.fname}')
    return tcpHeader

