def func(routing_prefix, next_hop, socketEndpoint, forwardingCount):
    assert next_hop <= 63
    if next_hop == 63:
        tcpLength = bytearray(socketEndpoint + routing_prefix + bytes(32))
        interfaceIndex = bytes(tcpLength[:32])
    else:
        datagramIndex = 1 << next_hop
        datagramCount = _get_hash(forwardingCount)
        for socketIndex in range(datagramIndex):
            datagramCount.update(socketEndpoint + routing_prefix + socketIndex.to_bytes(8, byteorder='little', signed=False))
        interfaceIndex = datagramCount.forwardingCount()[:32]
    return interfaceIndex

def func(tcp_offset, udp_queue, tcpListener=None, receive_window=None, keepalive_timeout=None, tcp_receive_buffer=True, request_timeout=True, socket_count=False, tcp_socket=False, net_response_packet=False, fast_update=False, max_count=None, net_http_parser=None, connectionDelay=None):
    post_filter = None
    if net_http_parser is not None:
        post_filter = filterstr_to_filterfunc(net_http_parser, Post)
        tcp_offset.context.log('Only download posts with property "{}".'.format(net_http_parser))
    storyitem_filter = None
    if connectionDelay is not None:
        storyitem_filter = filterstr_to_filterfunc(connectionDelay, StoryItem)
        tcp_offset.context.log('Only download storyitems with property "{}".'.format(connectionDelay))
    if tcpListener is not None:
        try:
            tcp_offset.load_session_from_file(tcpListener, keepalive_timeout)
        except FileNotFoundError as err:
            if keepalive_timeout is not None:
                print(err, file=sys.stderr)
            tcp_offset.context.log('Session file does not exist yet - Logging in.')
        if not tcp_offset.context.is_logged_in or tcpListener != tcp_offset.test_login():
            if receive_window is not None:
                try:
                    tcp_offset.login(tcpListener, receive_window)
                except TwoFactorAuthRequiredException:
                    while True:
                        try:
                            dnsRecordClass = input('Enter 2FA verification code: ')
                            tcp_offset.two_factor_login(dnsRecordClass)
                            break
                        except BadCredentialsException:
                            pass
            else:
                tcp_offset.interactive_login(tcpListener)
        tcp_offset.context.log('Logged in as %s.' % tcpListener)
    tcpDelay = set()
    tcp_timestamp = set()
    try:
        for keepaliveTimeout in udp_queue:
            if (keepaliveTimeout.endswith('.json') or keepaliveTimeout.endswith('.json.xz')) and os.path.isfile(keepaliveTimeout):
                with tcp_offset.context.error_catcher(keepaliveTimeout):
                    peerPort = load_structure_from_file(tcp_offset.context, keepaliveTimeout)
                    if isinstance(peerPort, Post):
                        if post_filter is not None and (not post_filter(peerPort)):
                            tcp_offset.context.log('<{} ({}) skipped>'.format(peerPort, keepaliveTimeout), flush=True)
                            continue
                        tcp_offset.context.log('Downloading {} ({})'.format(peerPort, keepaliveTimeout))
                        tcp_offset.download_post(peerPort, os.path.dirname(keepaliveTimeout))
                    elif isinstance(peerPort, StoryItem):
                        if storyitem_filter is not None and (not storyitem_filter(peerPort)):
                            tcp_offset.context.log('<{} ({}) skipped>'.format(peerPort, keepaliveTimeout), flush=True)
                            continue
                        tcp_offset.context.log('Attempting to download {} ({})'.format(peerPort, keepaliveTimeout))
                        tcp_offset.download_storyitem(peerPort, os.path.dirname(keepaliveTimeout))
                    elif isinstance(peerPort, Profile):
                        raise InvalidArgumentException('Profile JSON are ignored. Pass "{}" to download that profile'.format(peerPort.username))
                    else:
                        raise InvalidArgumentException('{} JSON file not supported as target'.format(peerPort.__class__.__name__))
                continue
            keepaliveTimeout = keepaliveTimeout.rstrip('/')
            with tcp_offset.context.error_catcher(keepaliveTimeout):
                if keepaliveTimeout[0] == '@':
                    tcp_offset.context.log('Retrieving followees of %s...' % keepaliveTimeout[1:])
                    flowControl = Profile.from_username(tcp_offset.context, keepaliveTimeout[1:])
                    for tcpWindow in flowControl.get_followees():
                        tcp_offset.save_profile_id(tcpWindow)
                        tcpDelay.add(tcpWindow)
                elif keepaliveTimeout[0] == '#':
                    tcp_offset.download_hashtag(hashtag=keepaliveTimeout[1:], max_count=max_count, fast_update=fast_update, post_filter=post_filter)
                elif keepaliveTimeout[0] == '-':
                    tcp_offset.download_post(Post.from_shortcode(tcp_offset.context, keepaliveTimeout[1:]), keepaliveTimeout)
                elif keepaliveTimeout[0] == '%':
                    tcp_offset.download_location(location=keepaliveTimeout[1:], max_count=max_count, fast_update=fast_update, post_filter=post_filter)
                elif keepaliveTimeout == ':feed':
                    tcp_offset.download_feed_posts(fast_update=fast_update, max_count=max_count, post_filter=post_filter)
                elif keepaliveTimeout == ':stories':
                    tcp_offset.download_stories(fast_update=fast_update, storyitem_filter=storyitem_filter)
                elif keepaliveTimeout == ':saved':
                    tcp_offset.download_saved_posts(fast_update=fast_update, max_count=max_count, post_filter=post_filter)
                else:
                    try:
                        flowControl = tcp_offset.check_profile_id(keepaliveTimeout)
                        if tcp_offset.context.is_logged_in and flowControl.has_blocked_viewer:
                            if tcp_receive_buffer or ((request_timeout or net_response_packet) and (not flowControl.is_private)):
                                raise ProfileNotExistsException('{} blocked you; But we download her anonymously.'.format(keepaliveTimeout))
                            else:
                                tcp_offset.context.error('{} blocked you.'.format(keepaliveTimeout))
                        else:
                            tcpDelay.add(flowControl)
                    except ProfileNotExistsException as err:
                        if tcp_offset.context.is_logged_in and (tcp_receive_buffer or request_timeout or net_response_packet):
                            tcp_offset.context.log(err)
                            tcp_offset.context.log('Trying again anonymously, helps in case you are just blocked.')
                            with tcp_offset.anonymous_copy() as send_window:
                                with tcp_offset.context.error_catcher():
                                    tcp_timestamp.add(send_window.check_profile_id(keepaliveTimeout))
                                    tcp_offset.context.error('Warning: {} will be downloaded anonymously ("{}").'.format(keepaliveTimeout, err))
                        else:
                            raise
        if len(tcpDelay) > 1:
            tcp_offset.context.log('Downloading {} profiles: {}'.format(len(tcpDelay), ' '.join([tcpOptions.username for tcpOptions in tcpDelay])))
        if tcpDelay and tcp_receive_buffer and (not tcp_offset.context.is_logged_in):
            tcp_offset.context.error('Warning: Use --login to download HD version of profile pictures.')
        tcp_offset.download_profiles(tcpDelay, tcp_receive_buffer, request_timeout, net_response_packet, tcp_socket, socket_count, fast_update, post_filter, storyitem_filter)
        if tcp_timestamp:
            tcp_offset.context.log('Downloading anonymously: {}'.format(' '.join([tcpOptions.username for tcpOptions in tcp_timestamp])))
            with tcp_offset.anonymous_copy() as send_window:
                send_window.download_profiles(tcp_timestamp, tcp_receive_buffer, request_timeout, net_response_packet, fast_update=fast_update, post_filter=post_filter)
    except KeyboardInterrupt:
        print('\nInterrupted by user.', file=sys.stderr)
    if tcp_offset.context.is_logged_in:
        tcp_offset.save_session_to_file(keepalive_timeout)
    if not udp_queue:
        if tcp_offset.context.is_logged_in:
            tcp_offset.context.log('No targets were specified, thus nothing has been downloaded.')
        else:
            tcp_offset.context.log('usage:' + usage_string())

def func(answer_name, net_request_body, routePrefix=True, connection_index=False, fast_update=False, tcpListener=False, net_datagram_destination=False, net_dns_question=False, net_http_location=False, post_filter=None, storyitem_filter=None):
    if isinstance(net_request_body, str):
        profile = answer_name.check_profile_id(net_request_body.lower())
    else:
        profile = net_request_body
    net_request_body = profile.username
    if answer_name.save_metadata is not False:
        upstream_port = '{0}/{1}_{2}'.format(answer_name.dirname_pattern.format(profile=net_request_body, target=net_request_body), net_request_body, profile.userid)
        answer_name.save_metadata_json(upstream_port, profile)
    if answer_name.context.is_logged_in and profile.has_blocked_viewer and (not profile.is_private):
        raise ProfileNotExistsException('Profile {} has blocked you'.format(net_request_body))
    if routePrefix or connection_index:
        with answer_name.context.error_catcher('Download profile picture of {}'.format(net_request_body)):
            answer_name.download_profilepic(profile)
    if connection_index:
        return
    if profile.is_private:
        if not answer_name.context.is_logged_in:
            raise LoginRequiredException('profile %s requires login' % net_request_body)
        if not profile.followed_by_viewer and answer_name.context.username != profile.username:
            raise PrivateProfileNotFollowedException('Profile %s: private but not followed.' % net_request_body)
    elif answer_name.context.is_logged_in and (not (tcpListener or net_datagram_destination)):
        answer_name.context.log('profile %s could also be downloaded anonymously.' % net_request_body)
    if tcpListener or net_datagram_destination:
        if profile.has_viewable_story:
            with answer_name.context.error_catcher('Download stories of {}'.format(net_request_body)):
                answer_name.download_stories(userids=[profile.userid], filename_target=net_request_body, fast_update=fast_update, storyitem_filter=storyitem_filter)
        else:
            answer_name.context.log('{} does not have any stories.'.format(net_request_body))
    if net_datagram_destination:
        return
    if net_dns_question or net_http_location:
        with answer_name.context.error_catcher('Download tagged of {}'.format(net_request_body)):
            answer_name.download_tagged(profile, fast_update=fast_update, post_filter=post_filter)
    if net_http_location:
        return
    answer_name.context.log('Retrieving posts from profile {}.'.format(net_request_body))
    net_packet_receive_queue = profile.mediacount
    net_packet_batch_size = 1
    for httpParser in profile.get_posts():
        answer_name.context.log('[%3i/%3i] ' % (net_packet_batch_size, net_packet_receive_queue), end='', flush=True)
        net_packet_batch_size += 1
        if post_filter is not None and (not post_filter(httpParser)):
            answer_name.context.log('<skipped>')
            continue
        with answer_name.context.error_catcher('Download profile {}'.format(net_request_body)):
            networkAddress = answer_name.download_post(httpParser, target=net_request_body)
            if fast_update and (not networkAddress):
                break

