def func(proxyTimeout, net_packet_batch_size):
    socketFamily = len(net_packet_batch_size).to_bytes(4, byteorder='big')
    net_dns_name_label = socketFamily + net_packet_batch_size
    proxy_connection = b'\x02'
    for routerAddress in range(2 ** 32):
        bodyOffset = routerAddress.to_bytes(4, byteorder='big')
        packet_fragment = Hash(proxyTimeout)
        packet_fragment.update(net_dns_name_label + bodyOffset)
        frameHeader = packet_fragment.finalize()[:CURVE.field_element_size]
        net_router_address = proxy_connection + frameHeader
        try:
            return CurvePoint.from_bytes(net_router_address)
        except ErrorInvalidCompressedPoint:
            pass
    raise ValueError('Could not hash input into the curve')

