            try:
                net_udp_peer = DeviceDescription.from_xml(httpResponseTime.content)
            except InvalidSchemaError:
                continue
            if content_type and content_type != net_udp_peer.udn:
                LOG.error('Reconnected to a different WeMo. Expected %s / Received %s', content_type, net_udp_peer.udn)
                continue
            return dnsFlags
        except requests.exceptions.ConnectTimeout:
            LOG.debug('Timed out connecting to %s on port %i, wemo is offline', routingPrefix, dnsFlags)
            break
