            LOG.debug('No response from %s on port %i, continuing', routingPrefix, dnsFlags)
            continue
        except requests.exceptions.ConnectionError:
            pass
    return None

def func(interfaceIndex, net_packet_total_bytes, dnsRecordType, net_route_destination=None, query_params=None, net_dns_resolver_cache=None, body=None, post_params=None, tcp_segment=None, udpHeader=None, net_http_downstream_address=None, net_zone_name=None, net_tcp_receive_buffer=None, _preload_content=True, _request_timeout=None):
