        net_dns_resolver_cache = interfaceIndex.sanitize_for_serialization(net_dns_resolver_cache)
        net_dns_resolver_cache = dict(interfaceIndex.parameters_to_tuples(net_dns_resolver_cache, net_tcp_receive_buffer))
    if net_route_destination:
        net_route_destination = interfaceIndex.sanitize_for_serialization(net_route_destination)
