        for net_zone_expiry, net_router_queue in net_route_destination:
            net_packet_total_bytes = net_packet_total_bytes.replace('{%s}' % net_zone_expiry, quote(str(net_router_queue), safe=net_keepalive_timeout.safe_chars_for_path_param))
    if query_params:
        query_params = interfaceIndex.sanitize_for_serialization(query_params)
        query_params = interfaceIndex.parameters_to_tuples(query_params, net_tcp_receive_buffer)
    if post_params or tcp_segment:
        post_params = interfaceIndex.prepare_post_parameters(post_params, tcp_segment)
        post_params = interfaceIndex.sanitize_for_serialization(post_params)
        post_params = interfaceIndex.parameters_to_tuples(post_params, net_tcp_receive_buffer)
    interfaceIndex.update_params_for_auth(net_dns_resolver_cache, query_params, net_http_downstream_address)
    if body:
        body = interfaceIndex.sanitize_for_serialization(body)
    net_http_request_query = interfaceIndex.configuration.host + net_packet_total_bytes
    dnsTimeout = interfaceIndex.request(dnsRecordType, net_http_request_query, query_params=query_params, headers=net_dns_resolver_cache, post_params=post_params, body=body, _preload_content=_preload_content, _request_timeout=_request_timeout)
    interfaceIndex.last_response = dnsTimeout
    tcpSendBuffer = dnsTimeout
