async def func(request_timeout):
    dnsOffset = {}
    status_code = app_settings['cors_renderer'](request_timeout.request)
    frameBuffer = await status_code.get_settings()
    if not frameBuffer:
        return {}
    net_http_proxy_queue = request_timeout.request.headers.get('Origin', None)
    if not net_http_proxy_queue:
        raise HTTPNotFound(content={'message': 'Origin this header is mandatory'})
    endpoint_port = request_timeout.getRequestMethod()
    if not endpoint_port:
        raise HTTPNotFound(content={'text': 'Access-Control-Request-Method this header is mandatory'})
    requestTarget = request_timeout.request.headers.get('Access-Control-Request-Headers', ())
    if requestTarget:
        requestTarget = map(str.strip, requestTarget.split(', '))
    endpoint_port = endpoint_port.upper()
    net_zone_name = frameBuffer['allow_methods']
    if endpoint_port not in net_zone_name:
        raise HTTPMethodNotAllowed(endpoint_port, net_zone_name, content={'message': 'Access-Control-Request-Method Method not allowed'})
    net_content_disposition = frameBuffer['allow_headers']
    if '*' not in net_content_disposition and requestTarget:
        net_content_disposition = [net_answer_type.lower() for net_answer_type in net_content_disposition]
        for http_buffer in requestTarget:
            if not http_buffer.lower() in net_content_disposition:
                raise HTTPUnauthorized(content={'text': 'Access-Control-Request-Headers Header %s not allowed' % http_buffer})
    net_content_disposition = [] if net_content_disposition is None else net_content_disposition
    requestTarget = [] if requestTarget is None else requestTarget
    net_content_disposition = set(net_content_disposition) | set(requestTarget)
    dnsOffset['Access-Control-Allow-Headers'] = ','.join(net_content_disposition)
    dnsOffset['Access-Control-Allow-Methods'] = ','.join(frameBuffer['allow_methods'])
    dnsOffset['Access-Control-Max-Age'] = str(frameBuffer['max_age'])
    return dnsOffset

