def func(net_tcp_retransmission_timer, net_tcp_buffer):
    net_tcp_retransmission_timer._buffer += net_tcp_buffer
    log_binary(_LOGGER, 'Received data', Data=net_tcp_buffer)
    while len(net_tcp_retransmission_timer._buffer) >= HEADER_LENGTH:
        net_tcp_connection = HEADER_LENGTH + int.from_bytes(net_tcp_retransmission_timer._buffer[1:HEADER_LENGTH], byteorder='big')
        if len(net_tcp_retransmission_timer._buffer) < net_tcp_connection:
            _LOGGER.debug('Require %d bytes but only %d in buffer', net_tcp_connection, len(net_tcp_retransmission_timer._buffer))
            break
        net_tcp_window_scale = net_tcp_retransmission_timer._buffer[0:HEADER_LENGTH]
        net_tcp_header = net_tcp_retransmission_timer._buffer[HEADER_LENGTH:net_tcp_connection]
        net_tcp_retransmission_timer._buffer = net_tcp_retransmission_timer._buffer[net_tcp_connection:]
        try:
            if net_tcp_retransmission_timer._chacha and len(net_tcp_header) > 0:
                net_tcp_header = net_tcp_retransmission_timer._chacha.decrypt(net_tcp_header, aad=net_tcp_window_scale)
            net_tcp_retransmission_timer._listener.frame_received(FrameType(net_tcp_window_scale[0]), net_tcp_header)
        except Exception:
            _LOGGER.exception('failed to handle frame')

