async def func(net_tcp_socket_family, net_tcp_socket_buffer, net_tcp_congestion_window=True):
    if not isinstance(net_tcp_socket_buffer, list):
        net_tcp_socket_buffer = [net_tcp_socket_buffer]
    net_tcp_slow_start_threshold = []
    for net_tcp_buffer in net_tcp_socket_buffer:
        if not isinstance(net_tcp_buffer, dict):
            raise KongError('dictionary required')
        net_tcp_buffer = net_tcp_buffer.copy()
        net_tcp_connection_endpoint = net_tcp_buffer.pop('groups', [])
        net_tcp_keepalive_timeout = net_tcp_buffer.pop('auths', [])
        net_tcp_received_bytes = net_tcp_buffer.copy()
        net_tcp_send_bytes = net_tcp_received_bytes.pop('id', None)
        net_tcp_send_buffer = None
        if not net_tcp_send_bytes:
            net_tcp_send_buffer = net_tcp_received_bytes.pop('username', None)
            if not net_tcp_send_buffer:
                raise KongError('Consumer username or id is required')
        net_tcp_segment_buffer = cast(str, net_tcp_send_bytes or net_tcp_send_buffer)
        try:
            net_tcp_stream_buffer = await net_tcp_socket_family.get(net_tcp_segment_buffer)
        except KongResponseError as exc:
            if exc.status == 404:
                net_tcp_stream_buffer = await net_tcp_socket_family.create(**net_tcp_buffer)
            else:
                raise
        else:
            if net_tcp_buffer:
                net_tcp_stream_buffer = await net_tcp_socket_family.update(net_tcp_segment_buffer, **net_tcp_received_bytes)
        net_tcp_packet_buffer = cast(Consumer, net_tcp_stream_buffer)
        net_tcp_retransmit_queue = await net_tcp_packet_buffer.acls.get_list()
        net_tcp_receive_buffer = dict(((net_tcp_sent_bytes['group'], net_tcp_sent_bytes) for net_tcp_sent_bytes in net_tcp_retransmit_queue))
        for group in net_tcp_connection_endpoint:
            if group not in net_tcp_receive_buffer:
                await net_tcp_packet_buffer.acls.create(group=group)
            else:
                net_tcp_receive_buffer.pop(group)
        for net_tcp_header_bytes in net_tcp_receive_buffer.values():
            await net_tcp_packet_buffer.acls.delete(net_tcp_header_bytes['id'])
        await net_tcp_socket_family.apply_credentials(net_tcp_keepalive_timeout, net_tcp_packet_buffer)
        net_tcp_slow_start_threshold.append(net_tcp_packet_buffer.data)
    return net_tcp_slow_start_threshold

def func(ethernetHeader, routing_metric, datagramCount):
    cast(Tuple[cirq.LineQubit], datagramCount)
    route_prefix = len(datagramCount)
    packet_data = np.zeros(route_prefix)
    datagram_source = []
    for subnetAddress in routing_metric.qubits:
        packetReceiver = datagramCount.index(subnetAddress)
        datagram_source.append(packetReceiver)
        packet_bytes = [packetReceiver - 1, packetReceiver + 1]
        for sourceAddress in packet_bytes:
            if sourceAddress >= 0 and sourceAddress < route_prefix:
                packet_data[sourceAddress] = ethernetHeader.noise_op_dict['crosstalk']
    for packetReceiver in datagram_source:
        packet_data[packetReceiver] = 0
    routing_prefix = []
    routingPrefix = get_op_string(routing_metric)
    router_interface = cast(cirq.EigenGate, gate_dict[routingPrefix])
    if len(routing_metric.qubits) == 1:
        for packetReceiver in packet_data.nonzero()[0]:
            packet_channel = routing_metric.gate.exponent
            packet_channel = packet_channel * packet_data[packetReceiver]
            link_speed = router_interface.on(datagramCount[packetReceiver]) ** packet_channel
            routing_prefix.append(link_speed)
    elif len(routing_metric.qubits) == 2:
        for frameLength in routing_metric.qubits:
            for packetReceiver in packet_data.nonzero()[0]:
                packet_channel = routing_metric.gate.exponent
                packet_channel = packet_channel * packet_data[packetReceiver]
                link_speed = router_interface.on(frameLength, datagramCount[packetReceiver]) ** packet_channel
                routing_prefix.append(link_speed)
    return routing_prefix

def func(tcp_window, send_length):
    streamLength, localPort = send_length.start
    connectionIndex, streamBuffer = send_length.end
    connection_handle = send_length.line.splitlines(keepends=True)
    tcpOffset = connectionIndex - streamLength
    peer_port = 0
    if not connection_handle or (peer_port == tcpOffset and localPort == streamBuffer):
        return ''
    tcp_peer = []
    if tcp_window.last_line != streamLength:
        tcp_window.last_col = 0
    if tcp_window.last_col < localPort:
        tcp_peer.append(connection_handle[0][tcp_window.last_col:localPort])
    tcp_window.last_line = connectionIndex
    tcp_window.last_col = streamBuffer
    if peer_port == tcpOffset:
        tcp_peer.append(connection_handle[peer_port][localPort:streamBuffer])
    else:
        tcp_peer.append(connection_handle[peer_port][localPort:])
        for udp_length in range(peer_port + 1, tcpOffset):
            tcp_peer.append(connection_handle[udp_length])
        tcp_peer.append(connection_handle[tcpOffset][:streamBuffer])
    return ''.join(tcp_peer)

def func(iou, httpMethod, record_length, queryValue):
    if record_length == 0:
        if iou is not None:
            log.debug('Discarding IOU, service fee is 0', sender=to_checksum_address(iou.sender), total_amount=iou.amount, claimable_until=iou.claimable_until)
        else:
            log.debug('No IOU and service fee is 0')
        return
    if iou is None:
        raise exceptions.MissingIOU
    log.debug('Checking IOU', sender=to_checksum_address(iou.sender), total_amount=iou.amount, claimable_until=iou.claimable_until)
    if not is_same_address(iou.receiver, httpMethod.address):
        raise exceptions.WrongIOURecipient(expected=httpMethod.address)
    if iou.chain_id != httpMethod.chain_id:
        raise exceptions.UnsupportedChainID(expected=httpMethod.chain_id)
    if iou.one_to_n_address != queryValue:
        raise exceptions.WrongOneToNAddress(expected=queryValue, got=iou.one_to_n_address)
    if not iou.is_signature_valid():
        raise exceptions.InvalidSignature
    net_dns_record_length = httpMethod.blockchain_state.latest_committed_block
    query_class = httpMethod.database.get_iou(sender=iou.sender, claimed=False)
    if query_class:
        if query_class.claimable_until != iou.claimable_until:
            raise exceptions.UseThisIOU(iou=query_class.Schema().dump(query_class))
        expected_amount = query_class.amount + record_length
    else:
        upstreamPort = httpMethod.database.get_iou(sender=iou.sender, claimable_until=iou.claimable_until, claimed=True)
        if upstreamPort:
            raise exceptions.IOUAlreadyClaimed
        min_expiry = get_posix_utc_time_now() + MIN_IOU_EXPIRY
        if iou.claimable_until < min_expiry:
            raise exceptions.IOUExpiredTooEarly(min_expiry=min_expiry, claimable_until_received=iou.claimable_until)
        expected_amount = record_length
    if iou.amount < expected_amount:
        raise exceptions.InsufficientServicePayment(expected_amount=expected_amount, actual_amount=iou.amount)
    udc = httpMethod.user_deposit_contract
    tcpBacklog = get_pessimistic_udc_balance(udc=udc, address=iou.sender, from_block=BlockNumber(net_dns_record_length - httpMethod.required_confirmations), to_block=net_dns_record_length)
    required_deposit = round(expected_amount * UDC_SECURITY_MARGIN_FACTOR_PFS)
    if tcpBacklog < required_deposit:
        raise exceptions.DepositTooLow(required_deposit=required_deposit, seen_deposit=tcpBacklog, block_number=net_dns_record_length)
    log.info('Received service fee', sender=iou.sender, expected_amount=expected_amount, total_amount=iou.amount, added_amount=expected_amount - record_length)
    iou.claimed = False
    httpMethod.database.upsert_iou(iou)

