def func(reason_phrase, bodyStream):
    cache_directive = []
    httpResponseTime = bodyStream.header.pulses_per_quarter_note
    logger.debug('pulses per quarter note: %i', httpResponseTime)
    http_header_value = bodyStream.tracks[0].events[0][1].metadata['tempo']
    logger.debug('tempo: %i', http_header_value)
    http_agent = http_header_value / httpResponseTime
    logger.debug('ticklen: %f', http_agent)
    query_value = DEFAULT_TICKLEN / http_agent
    cache_directive.append('start')
    requestBuffer = 0
    for client_address, (http_header_count, requestChunk) in enumerate(bodyStream.tracks[1].events):
        if reason_phrase._max_tokens is not None:
            if len(cache_directive) >= reason_phrase._max_tokens:
                yield ' '.join(cache_directive[:reason_phrase._max_tokens])
                cache_directive = ['continue', *cache_directive[reason_phrase._max_tokens:]]
        requestBuffer += round(http_header_count / query_value)
        if requestChunk.event_type == 'NoteOn':
            requestLength = requestChunk.metadata
            if requestBuffer > 0:
                if cache_directive[-1] != 'start':
                    cache_directive.extend(split_waits(requestBuffer))
                requestBuffer = 0
            if requestLength['velocity'] > 0:
                request_count = 60
            else:
                request_count = 0
            cache_directive.append(f"note:{requestLength['key']}:{request_count}")
    cache_directive.append('end')
    if reason_phrase._max_tokens is not None:
        if len(cache_directive) >= reason_phrase._max_tokens:
            yield ' '.join(cache_directive[:reason_phrase._max_tokens])
            cache_directive = cache_directive[reason_phrase._max_tokens:]
    yield ' '.join(cache_directive)

