def func(reason_phrase, networkFrame):
    socket_buffer = 0
    hostAlias = len(reason_phrase) - 1
    while socket_buffer <= hostAlias and reason_phrase[socket_buffer] <= networkFrame <= reason_phrase[hostAlias]:
        net_response_index = math.floor(socket_buffer + (hostAlias - socket_buffer) * (networkFrame - reason_phrase[socket_buffer]) / (reason_phrase[hostAlias] - reason_phrase[socket_buffer]))
        if reason_phrase[net_response_index] == networkFrame:
            return net_response_index
        if reason_phrase[net_response_index] > networkFrame:
            hostAlias = net_response_index - 1
        else:
            socket_buffer = net_response_index + 1
    return -1

