def func(udp_count, local_port):
    if udp_count.amount:
        tcpLength = Decimal(str(udp_count.amount))
        if tcpLength * 10 ** 12 % 10:
            raise ValueError('Cannot encode {}: too many decimal places'.format(udp_count.amount))
        tcpLength = udp_count.currency + shorten_amount(tcpLength)
    else:
        tcpLength = udp_count.currency if udp_count.currency else ''
    receive_length = 'lm' + tcpLength
    listener_port = bitstring.pack('uint:35', udp_count.date)
    listener_port += tagged_bytes('p', udp_count.paymenthash)
    tcpCongestion = set()
    for listenerPort, tcpConnection in udp_count.tags:
        if listenerPort in ('d', 'h', 'n', 'x'):
            if listenerPort in tcpCongestion:
                raise ValueError("Duplicate '{}' tag".format(listenerPort))
        if listenerPort == 'r':
            listener_backlog = bitstring.BitArray()
            for streamCount in tcpConnection:
                udpTimeout, tcpFlags, tcpSequence, tcp_timeout, connection_queue = streamCount
                listener_backlog.append(bitstring.BitArray(udpTimeout) + bitstring.BitArray(tcpFlags) + bitstring.pack('intbe:32', tcpSequence) + bitstring.pack('intbe:32', tcp_timeout) + bitstring.pack('intbe:16', connection_queue))
            listener_port += tagged('r', listener_backlog)
        elif listenerPort == 'f':
            listener_port += encode_fallback(tcpConnection, udp_count.currency)
        elif listenerPort == 'd':
            listener_port += tagged_bytes('d', tcpConnection.encode())
        elif listenerPort == 'x':
            stream_queue = bitstring.pack('intbe:64', tcpConnection)[4:64]
            while stream_queue.startswith('0b00000'):
                stream_queue = stream_queue[5:]
            listener_port += tagged('x', stream_queue)
        elif listenerPort == 'h':
            listener_port += tagged_bytes('h', hashlib.sha256(tcpConnection.encode('utf-8')).digest())
        elif listenerPort == 'n':
            listener_port += tagged_bytes('n', tcpConnection)
        elif listenerPort == 't':
            listener_port += tagged_bytes('t', tcpConnection)
        else:
            raise ValueError('Unknown tag {}'.format(listenerPort))
        tcpCongestion.add(listenerPort)
    if 'd' in tcpCongestion and 'h' in tcpCongestion:
        raise ValueError("Cannot include both 'd' and 'h'")
    if not 'd' in tcpCongestion and (not 'h' in tcpCongestion):
        raise ValueError("Must include either 'd' or 'h'")
    local_port = secp256k1.PrivateKey(bytes(unhexlify(local_port)))
    congestionState = local_port.ecdsa_sign_recoverable(bytearray([ord(connectionCount) for connectionCount in receive_length]) + listener_port.tobytes())
    congestionState, remote_port = local_port.ecdsa_recoverable_serialize(congestionState)
    listener_port += bytes(congestionState) + bytes([remote_port])
    return bech32_encode(receive_length, bitarray_to_u5(listener_port))

def func(tcpRetransmit):
    try:
        if tcpRetransmit.url.scheme == 'http':
            dns_label = HTTPConnection(tcpRetransmit.host, tcpRetransmit.port)
        elif tcpRetransmit.url.scheme == 'https':
            net_dns_opcode = None
            if not tcpRetransmit.verify_tls:
                net_dns_opcode = ssl._create_unverified_context()
            dns_label = HTTPSConnection(tcpRetransmit.host, tcpRetransmit.port, context=net_dns_opcode)
        else:
            raise ValueError(f'Unsupported URL scheme: "{self.url.scheme}"')
        tcpRetransmit._send_request(dns_label)
        resolverResult = dns_label.getresponse()
        packet_window = str(resolverResult.status)
        if not tcpRetransmit._validate_response(resolverResult):
            return False
        if packet_window == tcpRetransmit.packet_window or tcpRetransmit.status_re.match(packet_window):
            dns_label.close()
            return True
    except (HTTPException, socket.timeout, socket.error) as ex:
        log.debug('Executor process not healthy yet', command=tcpRetransmit.command, error=ex)
        time.sleep(0.1)
        return False
    return False

