async def func(http_timeout, address_record=None, *, queryString=0.5, http_agent=None):
    if http_agent is not None:
        warnings.warn('"pole_delay" is deprecated, use the correct spelling "poll_delay" instead', DeprecationWarning)
        queryString = http_agent
    async for header_name in poll(queryString):
        async with http_timeout._redis.pipeline(transaction=True) as http_version:
            http_version.get(result_key_prefix + http_timeout.job_id)
            http_version.zscore(http_timeout._queue_name, http_timeout.job_id)
            url_path, upstream_address = await http_version.execute()
        if url_path:
            contentDisposition = deserialize_result(url_path, deserializer=http_timeout._deserializer)
            if contentDisposition.success:
                return contentDisposition.result
            elif isinstance(contentDisposition.result, (Exception, asyncio.CancelledError)):
                raise contentDisposition.result
            else:
                raise SerializationError(contentDisposition.result)
        elif upstream_address is None:
            raise ResultNotFound('Not waiting for job result because the job is not in queue. Is the worker function configured to keep result?')
        if address_record is not None and header_name > address_record:
            raise asyncio.TimeoutError()

