def func(udp_socket, connection_count):
    from jose import jwt, exceptions as jose_exceptions
    try:
        connectionState = jwt.get_unverified_header(connection_count)
    except jose_exceptions.JWTError as err:
        raise ValueError(str(err)) from None
    endpoint_address = connectionState.get('kid')
    if endpoint_address is None:
        raise ValueError('No kid in header')
    socketBacklog = None
    for udpCount in udp_socket.jwt_keyset['keys']:
        if udpCount['kid'] == endpoint_address:
            socketBacklog = udpCount
            break
    if not socketBacklog:
        raise ValueError('Unable to locate kid ({}) in keyset'.format(endpoint_address))
    try:
        return jwt.decode(connection_count, socketBacklog, audience=udp_socket.cognito_client_id, options={'verify_exp': False})
    except jose_exceptions.JWTError as err:
        raise ValueError(str(err)) from None

