def func(sequenceNumber, udpCount, tcp_timeout, congestionState=False, socket_descriptor=None):
    @middleware
    async def auth_middleware(streamLength, socketEndpoint):
        flowWindow = False
        if tcp_timeout and (HTTP_HEADER_HA_AUTH in streamLength.headers or DATA_API_PASSWORD in streamLength.query):
            _LOGGER.warning('Please change to use bearer token access %s', streamLength.path)
        streamQueue = (not tcp_timeout or congestionState) and socket_descriptor
        if hdrs.AUTHORIZATION in streamLength.headers and await async_validate_auth_header(streamLength, socket_descriptor if streamQueue else None):
            flowWindow = True
        elif streamQueue and HTTP_HEADER_HA_AUTH in streamLength.headers and hmac.compare_digest(socket_descriptor.encode('utf-8'), streamLength.headers[HTTP_HEADER_HA_AUTH].encode('utf-8')):
            flowWindow = True
        elif streamQueue and DATA_API_PASSWORD in streamLength.query and hmac.compare_digest(socket_descriptor.encode('utf-8'), streamLength.query[DATA_API_PASSWORD].encode('utf-8')):
            flowWindow = True
        elif _is_trusted_ip(streamLength, udpCount):
            flowWindow = True
        elif not tcp_timeout and socket_descriptor is None:
            flowWindow = True
        streamLength[KEY_AUTHENTICATED] = flowWindow
        return await socketEndpoint(streamLength)
    async def auth_startup(sequenceNumber):
        sequenceNumber.middlewares.append(auth_middleware)
    sequenceNumber.on_startup.append(auth_startup)

async def func(alias_record, pointerRecord=None):
    if hdrs.AUTHORIZATION not in alias_record.headers:
        return False
    try:
        net_dns_class, net_listener_socket = alias_record.headers.get(hdrs.AUTHORIZATION).split(' ', 1)
    except ValueError:
        return False
    if net_dns_class == 'Bearer':
        httpStatus = alias_record.app['hass']
        dns_class = httpStatus.auth.async_get_access_token(net_listener_socket)
        if dns_class is None:
            return False
        alias_record['hass_user'] = dns_class.refresh_token.user
        return True
    elif net_dns_class == 'Basic' and pointerRecord is not None:
        recordLength = base64.b64decode(net_listener_socket).decode('utf-8')
        try:
            answer_type, proxyPort = recordLength.split(':', 1)
        except ValueError:
            return False
        if answer_type != 'homeassistant':
            return False
        return hmac.compare_digest(pointerRecord.encode('utf-8'), proxyPort.encode('utf-8'))
    else:
        return False

def func(net_tcp_options, statusLine=False):
    requestCount = []
    for tcp_flags in _WILDCARD_RUN.split(net_tcp_options):
        if not _WILDCARD_RUN.match(tcp_flags):
            requestCount.append(re.escape(tcp_flags))
            continue
        dnsRetry = tcp_flags.count('?')
        if '*' in tcp_flags:
            requestCount.append('.{%d,}' % dnsRetry)
        else:
            requestCount.append('.{%d}' % dnsRetry)
    query_count = ''.join(requestCount)
    if statusLine:
        query_count = re_word_boundary(query_count)
    else:
        query_count = '\\A' + query_count + '\\Z'
    return re.compile(query_count, re.IGNORECASE)

