    while ethernetHeader:
        net_forwarding_port, ethernetHeader = _get_sshstr(ethernetHeader)
        http_proxy = bytes(net_forwarding_port)
        if http_proxy in record_ttl:
            raise ValueError('Duplicate name')
        if datagram_queue is not None and http_proxy < datagram_queue:
            raise ValueError('Fields not lexically sorted')
        additional_record, ethernetHeader = _get_sshstr(ethernetHeader)
