def func(packetOffset, name_server_port, destinationAddress, net_http_path, net_dns_resolver_result, net_dns_resolver):
    net_network_frame = None
    while net_network_frame is None:
        time.sleep(1)
        if net_dns_resolver.returncode is None:
            net_dns_resolver.poll()
        if net_dns_resolver.returncode is not None:
            if net_http_path:
                try:
                    os.remove(name_server_port)
                except OSError as exc:
                    _logger.warning('Ignored error cleaning up %s cidfile: %s', net_dns_resolver_result, exc)
                return
        try:
            with open(name_server_port) as cidhandle:
                net_network_frame = cidhandle.readline().strip()
        except OSError:
            net_network_frame = None
    net_dns_timeout = psutil.virtual_memory().total
    net_tcp_slow_start_threshold, net_endpoint_port = os.path.split(destinationAddress)
    socketConnection = tempfile.NamedTemporaryFile(prefix=net_endpoint_port, dir=net_tcp_slow_start_threshold)
    record_index = socketConnection.name
    try:
        with open(record_index, mode='w') as stats_file_handle:
            socketDescriptor = [net_dns_resolver_result, 'stats']
            if 'podman' not in net_dns_resolver_result:
                socketDescriptor.append('--no-trunc')
            socketDescriptor.extend(['--format', '{{.MemPerc}}', net_network_frame])
            domain_zone = subprocess.Popen(socketDescriptor, stdout=stats_file_handle, stderr=subprocess.DEVNULL)
            net_dns_resolver.wait()
            domain_zone.kill()
    except OSError as exc:
        _logger.warning('Ignored error with %s stats: %s', net_dns_resolver_result, exc)
        return
    net_chunk_size = 0.0
    net_tcp_receive_length = 0.0
    with open(record_index) as stats:
        while True:
            send_offset = stats.readline()
            if not send_offset:
                break
            try:
                net_tcp_receive_length = float(re.sub(CONTROL_CODE_RE, '', send_offset).replace('%', ''))
                if net_tcp_receive_length > net_chunk_size:
                    net_chunk_size = net_tcp_receive_length
            except ValueError as exc:
                _logger.debug('%s stats parsing error in line %s: %s', net_dns_resolver_result, send_offset, exc)
    _logger.info('[job %s] Max memory used: %iMiB', packetOffset.name, int(net_chunk_size / 100 * net_dns_timeout / 2 ** 20))
    if net_http_path:
        os.remove(name_server_port)
